"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useEffect, useRef, useState } from "react"

import { GaugeComposition } from "./composition"
import { clamp } from "./math"
import type { GaugeTransition } from "./transition"
import type { PlayMode } from "@/lib/gauge-kit/panels"
import type { GaugeSpec } from "@/lib/gauge-kit/spec"

export type AnimatedGaugeProps = {
  spec: GaugeSpec
  /** The gauge's own value; an inset's are inside the spec. */
  value: number
  mode: PlayMode
  /** Seconds per sweep leg, or between wander and jump targets. */
  period: number
  /** Wander range as a fraction of the domain, centred on the target. */
  amplitude: number
  /** Brings the whole composition up from the foot of each domain on mount. */
  sweepIn?: boolean
}

/** One gauge under the play mode: the domain it runs in, and where it rests. */
type Driven = { min: number; max: number; target: number }

/** Where a gauge goes on the next leg, reckoned against its own domain. */
const legOf = (
  { min, max, target }: Driven,
  from: number,
  mode: PlayMode,
  amplitude: number
) => {
  const span = max - min
  if (mode === "sweep") return from === max ? min : max
  if (mode === "jump") return min + Math.random() * span
  return clamp(target + (Math.random() * 2 - 1) * amplitude * span, min, max)
}

/**
 * Feeds the preview moving targets. Manual and jump settle with the spec's
 * own transition, so the preview shows exactly what the copied code does.
 * Sweep and wander glide between targets with a tween that lasts one period.
 *
 * Every gauge in the composition is driven, insets along with the host, each
 * in its own domain and around its own resting value. They keep one clock
 * between them, so a sweep runs them together, while jump and wander draw
 * for each of them separately.
 */
export const AnimatedGauge = ({
  spec,
  value,
  mode,
  period,
  amplitude,
  sweepIn = false,
}: AnimatedGaugeProps) => {
  const insets = spec.insets ?? []
  /* The host first and the insets after, which is the order `play` holds. */
  const driven: Driven[] = [
    { min: spec.domain.min, max: spec.domain.max, target: value },
    ...insets.map((inset) => ({
      min: inset.spec.domain.min,
      max: inset.spec.domain.max,
      target: inset.value,
    })),
  ]

  /* Read through a ref so the clock keeps up with a composition being edited
     without having to list it, and start over, on every render. */
  const latest = useRef(driven)
  useEffect(() => {
    latest.current = driven
  })

  const [play, setPlay] = useState<number[]>([])

  useEffect(() => {
    if (mode === "manual") return
    const next = () =>
      setPlay((prev) =>
        latest.current.map((gauge, i) =>
          legOf(gauge, prev[i] ?? gauge.target, mode, amplitude)
        )
      )
    // Start the first leg right away rather than after a full period.
    const first = window.setTimeout(next, 0)
    const id = window.setInterval(next, period * 1000)
    return () => {
      window.clearTimeout(first)
      window.clearInterval(id)
    }
  }, [mode, period, amplitude])

  const glide: GaugeTransition = {
    type: "tween",
    duration: period,
    ease: "easeInOut",
  }
  const settles = mode === "manual" || mode === "jump"
  /* A gauge rests where it was put until its first leg has been drawn. */
  const shown = (i: number) =>
    mode === "manual" ? driven[i].target : (play[i] ?? driven[i].target)

  /* An inset carries its own value and transition, so driving one is a matter
     of handing it the moving target in place of the value it was given. */
  const played =
    mode === "manual"
      ? spec
      : {
          ...spec,
          insets: insets.map((inset, i) => ({
            ...inset,
            value: shown(i + 1),
            spec: settles
              ? inset.spec
              : { ...inset.spec, transition: glide as GaugeTransition },
          })),
        }

  return (
    <GaugeComposition
      spec={played}
      value={shown(0)}
      transition={settles ? spec.transition : glide}
      sweepIn={sweepIn}
    />
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { arcPath, polar } from "./math"
import type { StrokeCap, Zone } from "./utils"

import { useGauge } from "./context"

type ArcStyleProps = {
  width?: number
  color?: string
  opacity?: number
  cap?: StrokeCap
  /** Radial offset from the reference radius. Positive moves outward. */
  offset?: number
  /** SVG dash pattern, for a broken ring. */
  dash?: string
}

/** The full background arc from `startAngle` to `endAngle`. */
export const GaugeTrack = ({
  width = 24,
  color = "currentColor",
  opacity = 0.15,
  cap = "round",
  offset = 0,
  dash,
}: ArcStyleProps) => {
  const { radius, startAngle, endAngle } = useGauge()
  return (
    <path
      d={arcPath(radius + offset, startAngle, endAngle)}
      fill="none"
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
      strokeDasharray={dash}
    />
  )
}

export type GaugeArcProps = ArcStyleProps & {
  /** Domain value the arc is anchored at. Defaults to `min`. */
  from?: number
  /** Domain value the arc ends at. Defaults to the current value. */
  to?: number
  /**
   * Grow the arc back from the end of the sweep instead of forward from its
   * start. The length is the same; only the end it is anchored to changes,
   * which is what a dial filling towards its start needs.
   */
  reverse?: boolean
  /**
   * Carry the arc on round a closed ring instead of clamping it at the
   * domain: a span from eleven at night to two in the morning crosses the
   * seam in one piece. The arc runs forward from `from` however far past
   * `max` the `to` reaches.
   */
  wrap?: boolean
}

/**
 * The filled arc, from `min` (or `from`) up to the current value (or `to`).
 * The ends may arrive either way round: an arc anchored above the value
 * grows back towards it, which is what a dial centred on zero needs.
 */
export const GaugeArc = ({
  width = 24,
  color = "currentColor",
  opacity = 1,
  cap = "round",
  offset = 0,
  from,
  to,
  reverse = false,
  wrap = false,
  dash,
}: GaugeArcProps) => {
  const { radius, min, max, value, startAngle, endAngle, angleOf } = useGauge()
  const tail = from ?? min
  const head = to ?? value
  const lo = Math.min(tail, head)
  const hi = Math.max(tail, head)

  let a0: number
  let a1: number
  if (wrap) {
    const span = max - min
    if (span <= 0) return null
    const perUnit = (endAngle - startAngle) / span
    a0 = startAngle + ((((lo - min) % span) + span) % span) * perUnit
    a1 = a0 + Math.min((hi - lo) * perUnit, 360)
  } else {
    ;[a0, a1] = reverse
      ? [angleOf(max - (hi - lo)), angleOf(max)]
      : [angleOf(lo), angleOf(hi)]
  }
  if (a1 <= a0) return null

  return (
    <path
      d={arcPath(radius + offset, a0, a1)}
      fill="none"
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
      strokeDasharray={dash}
    />
  )
}

export type GaugeStackPart = {
  /** Share of the fill. Weighted parts split the value between them. */
  weight?: number
  /** Fixed upper cutoff in domain units, for parts that stand still while
      the value sweeps across them. Runs from the end of the part before. */
  to?: number
  color: string
  opacity?: number
}

export type GaugeStackProps = Omit<ArcStyleProps, "color"> & {
  parts: GaugeStackPart[]
  /** Domain value the stack starts at. Defaults to `min`. */
  from?: number
}

/**
 * The value arc split into parts that sweep as one. A part with a `weight`
 * takes that share of the fill, so a memory ring keeps wired, app and cache
 * in proportion frame by frame; a part with a fixed `to` runs from the end
 * of the one before and is clipped to the value, so a night of sleep stages
 * draws on in order as the dial sweeps in. Use one kind or the other in a
 * single stack.
 */
export const GaugeStack = ({
  parts,
  width = 24,
  opacity = 1,
  cap = "butt",
  offset = 0,
  from,
}: GaugeStackProps) => {
  const { radius, min, value, angleOf } = useGauge()
  if (parts.length === 0) return null

  const total = parts.reduce((sum, p) => sum + (p.weight ?? 0), 0)
  const start = from ?? min
  const fill = value - start
  const r = radius + offset

  /* Each part runs from the end of the one before: its own cutoff, or its
     share of the fill. */
  const ends = parts.reduce<number[]>(
    (acc, p) => [
      ...acc,
      p.to ??
        (acc.at(-1) ?? start) +
          (total > 0 ? (fill * (p.weight ?? 0)) / total : 0),
    ],
    []
  )

  return (
    <g opacity={opacity}>
      {parts.map((p, i) => {
        const a0 = angleOf(i === 0 ? start : ends[i - 1])
        const a1 = angleOf(Math.min(ends[i], value))
        if (a1 <= a0) return null
        return (
          <path
            key={i}
            d={arcPath(r, a0, a1)}
            fill="none"
            stroke={p.color}
            strokeOpacity={p.opacity}
            strokeWidth={width}
            strokeLinecap={cap}
          />
        )
      })}
    </g>
  )
}

export type GaugeZonesProps = Omit<ArcStyleProps, "color"> & {
  /**
   * Ordered cutoffs. Each zone runs from the previous zone's `to` (or `min`)
   * up to its own `to`; the last zone always extends to `max`.
   */
  zones: Zone[]
  /** Gap between neighbouring zones, in degrees. */
  gap?: number
  /**
   * Cap on the two outer ends of the whole band (the start of the first zone
   * and the end of the last). `cap` covers the joints between zones. Defaults
   * to `cap`, so a single value still rounds or squares every end.
   */
  endCap?: StrokeCap
}

/** Coloured bands marking the cutoffs of the domain. */
export const GaugeZones = ({
  zones,
  width = 8,
  opacity = 1,
  cap = "butt",
  endCap = cap,
  offset = 0,
  gap = 0,
}: GaugeZonesProps) => {
  const { radius, min, max, angleOf } = useGauge()
  if (zones.length === 0) return null

  const r = radius + offset
  /* Segments are drawn with butt caps and rounded where asked with a disc of
     the stroke width, which is exactly the shape a round cap adds. Drawing
     the discs separately lets the joints and the outer ends differ. */
  const dot = (angle: number, color: string, key: string) => {
    const { x, y } = polar(r, angle)
    return <circle key={key} cx={x} cy={y} r={width / 2} fill={color} />
  }

  /* Each zone runs from the previous cutoff to its own, clamped to the domain. */
  const segments = zones.reduce<{ from: number; to: number }[]>(
    (acc, zone, i) => {
      const from = i === 0 ? min : acc[i - 1].to
      const isLast = i === zones.length - 1
      const to = isLast ? max : Math.min(Math.max(zone.to, from), max)
      acc.push({ from, to })
      return acc
    },
    []
  )

  return (
    <g opacity={opacity}>
      {zones.map((zone, i) => {
        const isFirst = i === 0
        const isLast = i === zones.length - 1
        const { from, to } = segments[i]
        const a0 = angleOf(from) + (isFirst ? 0 : gap / 2)
        const a1 = angleOf(to) - (isLast ? 0 : gap / 2)
        if (a1 <= a0) return null
        const startCap = isFirst ? endCap : cap
        const finishCap = isLast ? endCap : cap
        return (
          <g key={i}>
            <path
              d={arcPath(r, a0, a1)}
              fill="none"
              stroke={zone.color}
              strokeWidth={width}
              strokeLinecap="butt"
            />
            {startCap === "round" && dot(a0, zone.color, "start")}
            {finishCap === "round" && dot(a1, zone.color, "end")}
          </g>
        )
      })}
    </g>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { GaugeArc, GaugeTrack, GaugeZones } from "./arcs"
import { Gauge } from "./gauge"
import { GaugeInset } from "./inset"
import { GaugeDot } from "./dot"
import { GaugeHub, GaugeNeedle } from "./needle"
import { GaugeText, GaugeValue } from "./text"
import { GaugeMarks, GaugeTickLabels, GaugeTicks } from "./ticks"
import type { GaugeTransition } from "./transition"
import { clockLabel, compassLabel, zoneColor, zoneCutoffs } from "./utils"
import type { GaugeSpec } from "@/lib/gauge-kit/spec"

export type GaugeCompositionProps = {
  spec: GaugeSpec
  value: number
  /** Accessible name for the host meter. */
  label?: string
  className?: string
  /** Overrides the spec's transition, for play modes that drive their own. */
  transition?: GaugeTransition | boolean
  /**
   * Start every gauge in the composition at the bottom of its own domain and
   * let it animate up to the value it was given, so a whole composition
   * arrives with some movement in it rather than snapping into place. Each
   * gauge reads it once, as it mounts, so playing it again takes a remount.
   *
   * Nothing to do with the `sweep` play mode, which drives one value back and
   * forth for as long as it is on.
   */
  sweepIn?: boolean
}

/**
 * How far round a wrapping part is let travel as its gauge is played in. Well
 * under half a turn, so it arrives from near where it settles rather than
 * spinning across the dial to get there.
 */
const SWEEP_TURNS = 0.4

/**
 * Where a gauge starts when it is played in: the foot of its domain, so the
 * arc fills and the needle swings up from the bottom.
 *
 * Except that a part turning more than once over the domain would have to
 * spin all those times to get there, so a gauge carrying one is started
 * within reach instead — a clock's minute hand comes round a part of the way
 * rather than twelve times over. Nothing wrapping means nothing to rein in,
 * and the run stays the whole domain.
 */
const sweepFrom = (spec: GaugeSpec, value: number) => {
  const { min, max } = spec.domain
  const span = max - min
  const turns = Math.max(
    1,
    ...(spec.needles.show ? spec.needles.list.map((n) => n.turns) : []),
    ...(spec.dot.show ? [spec.dot.turns] : [])
  )
  const reach = turns > 1 ? (span / turns) * SWEEP_TURNS : span
  return Math.max(min, value - reach)
}

/**
 * Renders a `GaugeSpec` with the gauge primitives. The generated code in
 * `lib/gauge-code.ts` mirrors this composition, so keep the two in step.
 */
export const GaugeComposition = ({
  spec,
  value,
  label = "Gauge",
  className,
  transition = spec.transition,
  sweepIn = false,
}: GaugeCompositionProps) => {
  const { domain } = spec

  return (
    <Gauge
      value={value}
      min={domain.min}
      max={domain.max}
      startAngle={domain.startAngle}
      endAngle={domain.endAngle}
      radius={domain.radius}
      padding={domain.padding}
      fit={domain.fit}
      transition={transition}
      initialValue={sweepIn ? sweepFrom(spec, value) : undefined}
      label={label}
      className={className}
    >
      <GaugeParts spec={spec} value={value} />
      {spec.insets?.map((inset) => (
        <GaugeInset
          key={inset.name}
          label={inset.name}
          x={inset.x}
          y={inset.y}
          scale={inset.scale}
          value={inset.value}
          min={inset.spec.domain.min}
          max={inset.spec.domain.max}
          startAngle={inset.spec.domain.startAngle}
          endAngle={inset.spec.domain.endAngle}
          radius={inset.spec.domain.radius}
          transition={inset.spec.transition}
          initialValue={
            sweepIn ? sweepFrom(inset.spec, inset.value) : undefined
          }
        >
          <GaugeParts spec={inset.spec} value={inset.value} />
        </GaugeInset>
      ))}
    </Gauge>
  )
}

/**
 * Everything a spec draws inside its own gauge root, so an inset renders the
 * same way the host does. `value` is only needed for the zone the arc takes
 * its colour from; the parts themselves read the animated value from context.
 */
const GaugeParts = ({ spec, value }: { spec: GaugeSpec; value: number }) => {
  const { track, arc, zones, marks, majorTicks, minorTicks } = spec
  const { tickLabels, needles, dot, value: valueText, unit, title } = spec
  const labelFormat = { compass: compassLabel, clock: clockLabel }

  return (
    <>
      {spec.face.show && (
        <GaugeHub radius={spec.face.radius} color={spec.face.color} />
      )}
      {track.show && (
        <GaugeTrack
          width={track.width}
          color={track.color}
          opacity={track.opacity}
          cap={track.cap}
          offset={track.offset}
        />
      )}
      {zones.show && (
        <GaugeZones
          zones={zones.list}
          width={zones.width}
          offset={zones.offset}
          gap={zones.gap}
          cap={zones.cap}
          endCap={zones.endCap}
          opacity={zones.opacity}
        />
      )}
      {arc.show && (
        <GaugeArc
          width={arc.width}
          color={
            arc.colorByZone
              ? zoneColor(zones.list, value, arc.color)
              : arc.color
          }
          opacity={arc.opacity}
          cap={arc.cap}
          offset={arc.offset}
          reverse={arc.reverse}
        />
      )}
      {marks.show && (
        <GaugeMarks
          values={zoneCutoffs(zones.list)}
          length={marks.length}
          width={marks.width}
          color={marks.color}
          offset={marks.offset}
          cap={marks.cap}
        />
      )}
      {minorTicks.show && (
        <GaugeTicks
          count={minorTicks.count}
          length={minorTicks.length}
          width={minorTicks.width}
          color={minorTicks.color}
          offset={minorTicks.offset}
          cap={minorTicks.cap}
          opacity={minorTicks.opacity}
        />
      )}
      {majorTicks.show && (
        <GaugeTicks
          count={majorTicks.count}
          length={majorTicks.length}
          width={majorTicks.width}
          color={majorTicks.color}
          offset={majorTicks.offset}
          cap={majorTicks.cap}
          opacity={majorTicks.opacity}
        />
      )}
      {tickLabels.show && (
        <GaugeTickLabels
          count={tickLabels.count}
          offset={tickLabels.offset}
          fontSize={tickLabels.fontSize}
          color={tickLabels.color}
          font={tickLabels.font}
          weight={tickLabels.weight}
          decimals={tickLabels.decimals}
          format={
            tickLabels.format === "number"
              ? undefined
              : labelFormat[tickLabels.format]
          }
        />
      )}
      {needles.show &&
        needles.list.map((needle, i) => (
          <GaugeNeedle
            key={i}
            style={needle.style}
            length={needle.length}
            width={needle.width}
            color={needle.color}
            tail={needle.tail}
            tailColor={needle.tailColor}
            tailDot={needle.tailDot}
            gap={needle.gap}
            turns={needle.turns}
          />
        ))}
      {needles.show && (
        <GaugeHub radius={needles.hub.radius} color={needles.hub.color} />
      )}
      {dot.show && (
        <GaugeDot
          radius={dot.radius}
          color={dot.color}
          opacity={dot.opacity}
          offset={dot.offset}
          turns={dot.turns}
        />
      )}
      {valueText.show && (
        <GaugeValue
          x={valueText.x}
          y={valueText.y}
          fontSize={valueText.fontSize}
          color={valueText.color}
          font={valueText.font}
          weight={valueText.weight}
          anchor={valueText.anchor}
          decimals={valueText.decimals}
        />
      )}
      {unit.show && (
        <GaugeText
          x={unit.x}
          y={unit.y}
          fontSize={unit.fontSize}
          color={unit.color}
          font={unit.font}
          weight={unit.weight}
          anchor={unit.anchor}
        >
          {unit.text}
        </GaugeText>
      )}
      {title.show && (
        <GaugeText
          x={title.x}
          y={title.y}
          fontSize={title.fontSize}
          color={title.color}
          font={title.font}
          weight={title.weight}
          anchor={title.anchor}
        >
          {title.text}
        </GaugeText>
      )}
    </>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { createContext, useContext } from "react"

import { clamp, valueToAngle } from "./math"
import type { GaugeTransition } from "./transition"
import { useAnimatedValue } from "./use-animated-value"

export type GaugeContextValue = {
  /** Value being drawn this frame, clamped to the domain. Animated when the
      gauge has a transition. */
  value: number
  /** Value the gauge is heading for; equals `value` once settled. */
  target: number
  min: number
  max: number
  startAngle: number
  endAngle: number
  /** Radius of the gauge's reference circle in SVG units. */
  radius: number
  /** Maps a domain value onto a gauge angle. */
  angleOf: (value: number) => number
}

export const GaugeContext = createContext<GaugeContextValue | null>(null)

export const useGauge = () => {
  const ctx = useContext(GaugeContext)
  if (!ctx) {
    throw new Error("Gauge primitives must be rendered inside <Gauge>.")
  }
  return ctx
}

/** The domain, geometry and animation every gauge root takes. */
export type GaugeDomainProps = {
  value: number
  min?: number
  max?: number
  /** Gauge degrees, clockwise from six o'clock. */
  startAngle?: number
  endAngle?: number
  /** Reference radius in SVG units. Every child positions itself against this. */
  radius?: number
  /**
   * Animate towards new values. `true` uses a gentle spring; pass a
   * `GaugeTransition` to tune it or switch to a timed tween. Omit for
   * instant updates.
   */
  transition?: GaugeTransition | boolean
  /** Where the value starts on mount when animating, for a sweep-in effect. */
  initialValue?: number
  /**
   * Treat the domain as circular, as a compass rose or clock face is: the
   * value is mapped into the domain modulo its span and animates the
   * shortest way round, so a heading crossing north never swings the long
   * way back. Meant for closed rings, where `min` and `max` read the same.
   */
  wrap?: boolean
  /**
   * Turn the whole scale this many degrees clockwise, the way a compass card
   * turns under a fixed lubber line. Animated by `transition`, always the
   * shortest way round.
   */
  rotate?: number
}

/**
 * Resolves the domain and follows the value, returning the context a gauge
 * root publishes to its children. Shared by `Gauge` and `GaugeInset` so a
 * gauge nested inside another animates and maps values exactly like a
 * top-level one, and so the defaults live in one place.
 */
export const useGaugeContextValue = ({
  value,
  min = 0,
  max = 100,
  startAngle = 40,
  endAngle = 320,
  radius = 200,
  transition,
  initialValue,
  wrap = false,
  rotate = 0,
}: GaugeDomainProps): GaugeContextValue => {
  const lo = Math.min(min, max)
  const hi = Math.max(min, max)
  const span = hi - lo
  /* A wrapped domain folds any value back inside itself instead of clamping,
     so 370° on a compass reads as 10°. */
  const fold = (v: number) =>
    span === 0 ? lo : lo + ((((v - lo) % span) + span) % span)
  const settle = wrap ? fold : (v: number) => clamp(v, lo, hi)

  const target = settle(value)
  const shown = useAnimatedValue(
    target,
    transition,
    span,
    initialValue === undefined ? undefined : settle(initialValue),
    wrap
  )
  /* The rotation is a bearing, so it always takes the short way round. */
  const turned = useAnimatedValue(rotate, transition, 360, undefined, true)
  const a0 = startAngle + turned
  const a1 = endAngle + turned

  return {
    /* Folded when wrapped, otherwise as the spring left it, overshoot and
       all — a bounce past the end is part of the motion. */
    value: wrap ? fold(shown) : shown,
    target,
    min,
    max,
    startAngle: a0,
    endAngle: a1,
    radius,
    angleOf: (v) => valueToAngle(v, min, max, a0, a1),
  }
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import {
  useRef,
  type KeyboardEvent,
  type PointerEvent,
  type ReactNode,
} from "react"

import { cn } from "@/lib/utils"
import { angleToValue, clamp } from "./math"

/** How far out from the centre a press starts counting as the ring, as a
    share of the half width. Inside it is the face, left for `onPress`. */
const FACE = 0.55

/** Too near the centre for the angle under the pointer to mean anything. */
const HUB = 0.08

/** The gauge angle under a point, measured round the element's centre. */
const angleAt = (el: HTMLElement, x: number, y: number) => {
  const box = el.getBoundingClientRect()
  const dx = x - (box.left + box.width / 2)
  const dy = y - (box.top + box.height / 2)
  const theta = (Math.atan2(dy, dx) * 180) / Math.PI
  return {
    /* Gauge degrees start at six o'clock, a quarter turn behind the maths. */
    angle: (((theta - 90) % 360) + 360) % 360,
    /** How far out from the centre, as a share of the half width. */
    reach: Math.hypot(dx, dy) / (box.width / 2),
  }
}

export type GaugeControlProps = {
  value: number
  onChange: (value: number) => void
  /** A press on the middle of the face, or Enter, for a dial that is also a
      switch. Left out, the middle does nothing. */
  onPress?: () => void
  min?: number
  max?: number
  /** Granularity a drag lands on, and the size of an arrow-key step. */
  step?: number
  /** Gauge degrees, matching the gauge drawn inside. */
  startAngle?: number
  endAngle?: number
  /** Read to screen readers; every slider needs one. */
  label: string
  /** The value as it would be spoken: "21.5 °C" rather than 21.5. */
  valueText?: string
  /** The face turns like a knob: a drag anywhere on it moves the value by as
      far as the pointer goes round, rather than jumping to where it is. */
  knob?: boolean
  disabled?: boolean
  className?: string
  children: ReactNode
}

/**
 * Makes the square gauge inside it a slider: drag round the ring to set it,
 * or use the arrow keys, Page Up and Down, Home and End. A drag past either
 * end of the sweep holds there rather than jumping to the other. A press in
 * the middle of the face, or Enter, is left for `onPress`, which a dimmer
 * uses to switch on and off, or, with `knob`, turns the face from where it
 * is. The domain and angles default to `Gauge`'s own.
 */
export const GaugeControl = ({
  value,
  onChange,
  onPress,
  min = 0,
  max = 100,
  step = 1,
  startAngle = 40,
  endAngle = 320,
  label,
  valueText,
  knob = false,
  disabled = false,
  className,
  children,
}: GaugeControlProps) => {
  /* Whether the press that is down started in the middle of the face. */
  const pressed = useRef(false)
  /* A knob turn under way: the angle last seen, and the value it has got to
     before rounding to a step. */
  const turn = useRef<{ angle: number; value: number } | null>(null)

  const set = (next: number) =>
    onChange(clamp(Number(next.toFixed(2)), min, max))

  const valueUnder = (el: HTMLElement, x: number, y: number) => {
    const raw = angleToValue(
      angleAt(el, x, y).angle,
      min,
      max,
      startAngle,
      endAngle
    )
    return Math.round(raw / step) * step
  }

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (disabled) return
    const { angle, reach } = angleAt(e.currentTarget, e.clientX, e.clientY)
    if (reach < FACE && knob) {
      e.currentTarget.setPointerCapture(e.pointerId)
      turn.current = { angle, value }
      return
    }
    if (reach < FACE) {
      pressed.current = true
      return
    }
    e.currentTarget.setPointerCapture(e.pointerId)
    set(valueUnder(e.currentTarget, e.clientX, e.clientY))
  }

  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (!e.currentTarget.hasPointerCapture(e.pointerId)) return
    if (turn.current) {
      const { angle, reach } = angleAt(e.currentTarget, e.clientX, e.clientY)
      if (reach < HUB) return
      /* The shortest way round from the last angle, so crossing six o'clock
         is a small step and not a whole turn back. */
      const by = ((angle - turn.current.angle + 540) % 360) - 180
      const value = clamp(
        turn.current.value + (by / (endAngle - startAngle)) * (max - min),
        min,
        max
      )
      turn.current = { angle, value }
      set(Math.round(value / step) * step)
      return
    }
    set(valueUnder(e.currentTarget, e.clientX, e.clientY))
  }

  const onPointerUp = () => {
    if (pressed.current) onPress?.()
    pressed.current = false
    turn.current = null
  }

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return
    const big = (max - min) / 10
    const moves: Record<string, number> = {
      ArrowUp: value + step,
      ArrowRight: value + step,
      ArrowDown: value - step,
      ArrowLeft: value - step,
      PageUp: value + big,
      PageDown: value - big,
      Home: min,
      End: max,
    }
    if (e.key in moves) {
      e.preventDefault()
      set(moves[e.key])
    } else if ((e.key === "Enter" || e.key === " ") && onPress) {
      e.preventDefault()
      onPress()
    }
  }

  return (
    <div
      role="slider"
      tabIndex={disabled ? -1 : 0}
      aria-label={label}
      aria-valuemin={min}
      aria-valuemax={max}
      aria-valuenow={value}
      aria-valuetext={valueText}
      aria-disabled={disabled}
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={() => {
        pressed.current = false
        turn.current = null
      }}
      onKeyDown={onKeyDown}
      className={cn(
        "aspect-square touch-none rounded-full outline-none select-none focus-visible:ring-2 focus-visible:ring-ring",
        disabled ? "cursor-default" : "cursor-grab active:cursor-grabbing",
        className
      )}
    >
      {children}
    </div>
  )
}

