/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import type { SVGProps } from "react"

import { GaugeContext, useGaugeContextValue } from "./context"
import type { GaugeDomainProps } from "./context"

export type GaugeInsetProps = Omit<SVGProps<SVGGElement>, "transform"> &
  GaugeDomainProps & {
    /** Centre of the inset in the host gauge's SVG units. Positive y is down. */
    x?: number
    y?: number
    /** Size relative to the host gauge: 0.3 draws it at a third of the size. */
    scale?: number
    /** Accessible name for this nested meter. */
    label?: string
  }

/**
 * A whole gauge drawn inside another one: a fuel dial under a speedometer, a
 * second ring inside the first. It takes its own value and domain and sets up
 * the same context `Gauge` does, so every primitive works inside it unchanged.
 *
 * It draws in the host's coordinate system rather than its own viewport, so it
 * needs no `padding` or `fit`; `x`, `y` and `scale` place it, and everything
 * inside — strokes, ticks, text — shrinks with it. Its reference radius stays
 * the host's by default, which makes `scale` the only size to reason about.
 */
export const GaugeInset = ({
  value,
  min,
  max,
  startAngle,
  endAngle,
  radius,
  transition,
  initialValue,
  wrap,
  rotate,
  x = 0,
  y = 0,
  scale = 1,
  label = "Inset gauge",
  children,
  ...props
}: GaugeInsetProps) => {
  const gauge = useGaugeContextValue({
    value,
    min,
    max,
    startAngle,
    endAngle,
    radius,
    transition,
    initialValue,
    wrap,
    rotate,
  })

  return (
    <GaugeContext.Provider value={gauge}>
      <g
        transform={`translate(${x} ${y}) scale(${scale})`}
        {...props}
        role="meter"
        aria-label={label}
        aria-valuemin={gauge.min}
        aria-valuemax={gauge.max}
        aria-valuenow={gauge.target}
      >
        {children}
      </g>
    </GaugeContext.Provider>
  )
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * Pure geometry for the gauge primitives.
 *
 * Angles are "gauge degrees": 0 points straight down (six o'clock) and
 * values increase clockwise, so a sweep from 40° to 320° leaves an opening
 * at the bottom. Coordinates are SVG units centred on the gauge origin.
 */

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value))

export const degreesToRadians = (degrees: number) => (degrees * Math.PI) / 180

/**
 * Point on a circle of `radius` at a gauge angle. Coordinates are rounded so
 * server and client render identical attributes and hydration stays clean.
 */
export const polar = (radius: number, angle: number) => {
  const theta = degreesToRadians(angle + 90)
  return {
    x: round(radius * Math.cos(theta)),
    y: round(radius * Math.sin(theta)),
  }
}

const round = (n: number) => Math.round(n * 1000) / 1000

/** Linear map of a value in [min, max] onto the arc [startAngle, endAngle]. */
export const valueToAngle = (
  value: number,
  min: number,
  max: number,
  startAngle: number,
  endAngle: number
) => {
  const span = max - min
  const t = span === 0 ? 0 : (clamp(value, min, max) - min) / span
  return startAngle + t * (endAngle - startAngle)
}

/**
 * Angle for a value that wraps the arc more than once. A single turn maps the
 * domain onto the sweep exactly as `valueToAngle` does; past that each turn
 * runs the sweep again from its start, which is how a clock's minute hand
 * gets round twelve times while the hour hand goes round once.
 */
export const valueToTurnedAngle = (
  value: number,
  min: number,
  max: number,
  startAngle: number,
  endAngle: number,
  turns: number
) => {
  if (turns === 1) return valueToAngle(value, min, max, startAngle, endAngle)
  const span = max - min
  const t = span === 0 ? 0 : (value - min) / span
  return startAngle + ((t * turns) % 1) * (endAngle - startAngle)
}

/**
 * SVG path for an arc of `radius` from `from` to `to` gauge degrees. Sweeps
 * over 180° are split so a single `A` command never has to disambiguate a
 * large arc, which also makes a full 360° circle render correctly.
 */
export const arcPath = (radius: number, from: number, to: number) => {
  const sweep = Math.min(to - from, 360)
  if (sweep <= 0 || radius <= 0) return ""

  const pieces = Math.max(1, Math.ceil(sweep / 180))
  const step = sweep / pieces
  const start = polar(radius, from)
  const parts = [`M ${fmt(start.x)} ${fmt(start.y)}`]

  for (let i = 1; i <= pieces; i++) {
    const p = polar(radius, from + step * i)
    parts.push(`A ${fmt(radius)} ${fmt(radius)} 0 0 1 ${fmt(p.x)} ${fmt(p.y)}`)
  }

  return parts.join(" ")
}

/**
 * Tight bounding box of an arc sweep, inflated by `padding`. Takes the two
 * endpoints, every quarter turn the sweep crosses, and the origin, so a gauge
 * that pivots a needle keeps its hub inside the box. A sweep that closes on
 * itself crosses all four quarters and lands back on the full square.
 */
export const arcBox = (
  radius: number,
  from: number,
  to: number,
  padding = 0
) => {
  const sweep = clamp(to - from, 0, 360)
  const end = from + sweep
  const points = [{ x: 0, y: 0 }, polar(radius, from), polar(radius, end)]
  for (let a = Math.ceil(from / 90) * 90; a <= end; a += 90) {
    points.push(polar(radius, a))
  }

  const xs = points.map((p) => p.x)
  const ys = points.map((p) => p.y)
  const x = round(Math.min(...xs) - padding)
  const y = round(Math.min(...ys) - padding)

  return {
    x,
    y,
    width: round(Math.max(...xs) + padding - x),
    height: round(Math.max(...ys) + padding - y),
  }
}

/** Evenly spaced values across the domain, inclusive of both ends. */
export const stepValues = (min: number, max: number, intervals: number) => {
  const n = Math.max(1, Math.round(intervals))
  return Array.from({ length: n + 1 }, (_, i) => min + ((max - min) * i) / n)
}

/**
 * The cutoffs that split the domain into `segments` equal parts: the values
 * between the segments, none at the two ends. Ten glasses of water make nine
 * cuts.
 */
export const cutValues = (min: number, max: number, segments: number) =>
  stepValues(min, max, segments).slice(1, -1)

/**
 * Inverse of `valueToAngle`: the domain value under a gauge angle. An angle
 * in the opening outside the sweep goes to whichever end is nearer, so a
 * pointer dragged past an end holds there rather than jumping to the other.
 */
export const angleToValue = (
  angle: number,
  min: number,
  max: number,
  startAngle: number,
  endAngle: number
) => {
  let a = angle
  while (a < startAngle) a += 360
  while (a >= startAngle + 360) a -= 360
  if (a > endAngle) {
    a = a - endAngle < startAngle + 360 - a ? endAngle : startAngle
  }
  const sweep = endAngle - startAngle
  const t = sweep === 0 ? 0 : (a - startAngle) / sweep
  return min + t * (max - min)
}

const fmt = (n: number) => Number(n.toFixed(3)).toString()

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useId } from "react"

import { polar, valueToTurnedAngle } from "./math"
import type { NeedleStyle } from "./utils"

import { useGauge } from "./context"

export type GaugeNeedleProps = {
  /**
   * `line` is a stroke with round ends, `pointer` a tapered blade that is
   * widest at the centre and ends in a rounded tip, and `compass` a lozenge
   * whose two halves can take different colours. `arrow` is a shaft ending in
   * a triangular arrowhead, sized from the width, for wind or flow direction.
   */
  style?: NeedleStyle
  /** Length as a fraction of the reference radius. */
  length?: number
  /** Stroke width for `line`; width at the centre for the filled styles. */
  width?: number
  color?: string
  /** How far the needle extends behind the centre, in SVG units. */
  tail?: number
  /** Colour of the tail half of a `pointer`, `compass` or `arrow`. Defaults to `color`. */
  tailColor?: string
  /**
   * Radius of a disc drawn at the end of the tail in `tailColor`, like the
   * counterweight on a wind vane. 0 leaves the tail plain.
   */
  tailDot?: number
  /**
   * Sweeps of the arc the needle makes across the domain. A clock's minute
   * hand turns 12 times while the hour hand turns once.
   */
  turns?: number
  /**
   * Radius of a clear circle around the centre, in SVG units, that splits the
   * needle in two so a readout can sit between the halves. 0 draws it whole.
   */
  gap?: number
}

const pts = (points: { x: number; y: number }[]) =>
  points.map((p) => `${p.x},${p.y}`).join(" ")

/**
 * A needle pointing at the current value. Add a `GaugeHub` for the pivot, or
 * a `gap` to clear the centre for a readout instead.
 */
export const GaugeNeedle = ({ gap = 0, ...props }: GaugeNeedleProps) => {
  /* useId's output is not a safe fragment identifier, so keep word
     characters only. */
  const maskId = `gauge-needle-gap${useId().replace(/\W/g, "")}`
  if (gap <= 0) return <NeedleShape {...props} />

  /* A mask rather than geometry, so every style splits the same way. The
     cut edges follow the circle, which on a gap this much wider than the
     needle reads as straight. */
  return (
    <g>
      <mask
        id={maskId}
        maskUnits="userSpaceOnUse"
        x={-1e4}
        y={-1e4}
        width={2e4}
        height={2e4}
      >
        <rect x={-1e4} y={-1e4} width={2e4} height={2e4} fill="white" />
        <circle r={gap} fill="black" />
      </mask>
      <g mask={`url(#${maskId})`}>
        <NeedleShape {...props} />
      </g>
    </g>
  )
}

const NeedleShape = ({
  style = "line",
  length = 0.85,
  width = 6,
  color = "currentColor",
  tail = 30,
  tailColor = color,
  tailDot = 0,
  turns = 1,
}: Omit<GaugeNeedleProps, "gap">) => {
  const { radius, value, min, max, startAngle, endAngle } = useGauge()

  const angle = valueToTurnedAngle(value, min, max, startAngle, endAngle, turns)

  const tip = polar(radius * length, angle)
  const back = polar(-tail, angle)
  const endDot =
    tail > 0 && tailDot > 0 ? (
      <circle cx={back.x} cy={back.y} r={tailDot} fill={tailColor} />
    ) : null

  if (style === "arrow") {
    /* A shaft of `width` capped by a triangular head that scales with it,
       never longer than the needle itself. The shaft stops where the head
       begins so the two never overlap, and the tail is the shaft carried on
       behind the centre in its own colour, rounded off at the end. */
    const reach = radius * length
    const headLength = Math.min(width * 4, reach)
    const base = polar(reach - headLength, angle)
    const shaftLeft = polar(width / 2, angle - 90)
    const shaftRight = polar(width / 2, angle + 90)
    const headLeft = polar(width * 2, angle - 90)
    const headRight = polar(width * 2, angle + 90)
    const offset = (
      p: { x: number; y: number },
      d: { x: number; y: number }
    ) => ({
      x: p.x + d.x,
      y: p.y + d.y,
    })

    return (
      <g>
        {tail > 0 && (
          <>
            <polygon
              points={pts([
                shaftLeft,
                shaftRight,
                offset(back, shaftRight),
                offset(back, shaftLeft),
              ])}
              fill={tailColor}
            />
            <circle cx={back.x} cy={back.y} r={width / 2} fill={tailColor} />
          </>
        )}
        <polygon
          points={pts([
            shaftLeft,
            offset(base, shaftLeft),
            offset(base, headLeft),
            tip,
            offset(base, headRight),
            offset(base, shaftRight),
            shaftRight,
          ])}
          fill={color}
        />
        {endDot}
      </g>
    )
  }

  if (style === "line") {
    return (
      <>
        <line
          x1={back.x}
          y1={back.y}
          x2={tip.x}
          y2={tip.y}
          stroke={color}
          strokeWidth={width}
          strokeLinecap="round"
        />
        {endDot}
      </>
    )
  }

  /* The filled styles are two polygons meeting at the centre, so the tail can
     take its own colour. Their shared base runs across the pivot. Both ends
     keep a fifth of the width and are rounded off with a disc of that size,
     as a round cap would, so a thin needle never vanishes to a point. */
  const left = polar(width / 2, angle - 90)
  const right = polar(width / 2, angle + 90)
  const endRadius = width * 0.2
  const endLeft = polar(endRadius, angle - 90)
  const endRight = polar(endRadius, angle + 90)
  const blade = (end: { x: number; y: number }) =>
    pts([
      { x: end.x + endLeft.x, y: end.y + endLeft.y },
      { x: end.x + endRight.x, y: end.y + endRight.y },
      right,
      left,
    ])

  /* A pointer's tail is a blunt stub; a compass tapers the same both ways. */
  const rear =
    style === "compass"
      ? blade(back)
      : pts([
          { x: back.x + left.x * 0.6, y: back.y + left.y * 0.6 },
          { x: back.x + right.x * 0.6, y: back.y + right.y * 0.6 },
          right,
          left,
        ])

  return (
    <g>
      {tail > 0 && <polygon points={rear} fill={tailColor} />}
      {tail > 0 && style === "compass" && (
        <circle cx={back.x} cy={back.y} r={endRadius} fill={tailColor} />
      )}
      <polygon points={blade(tip)} fill={color} />
      <circle cx={tip.x} cy={tip.y} r={endRadius} fill={color} />
      {endDot}
    </g>
  )
}

export type GaugeHubProps = {
  radius?: number
  color?: string
}

/** The pivot disc at the centre, drawn once however many needles there are. */
