"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { cn } from "@/lib/utils"
import { cutValues, polar, stepValues } from "./math"
import type { GaugeContextValue } from "./context"
import {
  fontClass,
  weightClass,
  type FontFamily,
  type FontWeight,
  type StrokeCap,
} from "./utils"

import { useGauge } from "./context"

/**
 * Evenly spaced domain values for ticks. On a closed ring the last step lands
 * on the first, so it is dropped rather than drawn twice.
 */
const tickValues = (
  { min, max, startAngle, endAngle }: GaugeContextValue,
  count: number
) => {
  const values = stepValues(min, max, count)
  if (endAngle - startAngle >= 360) values.pop()
  return values
}

type RadialLineProps = {
  /** Length of each line along the radius. */
  length?: number
  width?: number
  color?: string
  opacity?: number
  cap?: StrokeCap
  /** Radial offset of the line's midpoint from the reference radius. */
  offset?: number
}

const RadialLines = ({
  angles,
  length = 12,
  width = 2,
  color = "currentColor",
  opacity = 1,
  cap = "round",
  offset = 0,
}: RadialLineProps & { angles: number[] }) => {
  const { radius } = useGauge()
  const inner = radius + offset - length / 2
  const outer = radius + offset + length / 2

  return (
    <g
      stroke={color}
      strokeOpacity={opacity}
      strokeWidth={width}
      strokeLinecap={cap}
    >
      {angles.map((angle, i) => {
        const a = polar(inner, angle)
        const b = polar(outer, angle)
        return <line key={i} x1={a.x} y1={a.y} x2={b.x} y2={b.y} />
      })}
    </g>
  )
}

export type GaugeTicksProps = RadialLineProps & {
  /** Number of intervals across the domain; renders `count + 1` ticks. */
  count?: number
}

/** Evenly spaced tick marks across the whole arc. */
export const GaugeTicks = ({ count = 10, ...props }: GaugeTicksProps) => {
  const gauge = useGauge()
  const angles = tickValues(gauge, count).map(gauge.angleOf)
  return <RadialLines angles={angles} {...props} />
}

export type GaugeMarksProps = RadialLineProps & {
  /** Domain values to mark, for example the cutoffs between zones. */
  values?: number[]
  /**
   * Cut the domain into this many equal segments instead: the marks fall
   * between the segments, none at the two ends. On a closed ring the seam is
   * cut too, since the last segment meets the first there. Drawn in the
   * surface's colour over a band, they slice it the way a water ring is cut
   * into glasses.
   */
  count?: number
}

/** Radial marks at arbitrary domain values, or at equal cuts of the domain. */
export const GaugeMarks = ({ values, count, ...props }: GaugeMarksProps) => {
  const { min, max, startAngle, endAngle, angleOf } = useGauge()
  const marks =
    values ??
    (count && count > 1
      ? [
          ...(endAngle - startAngle >= 360 ? [min] : []),
          ...cutValues(min, max, count),
        ]
      : [])
  return <RadialLines angles={marks.map(angleOf)} {...props} />
}

export type GaugeTickLabelsProps = {
  count?: number
  /** Radial offset of the label centre from the reference radius. */
  offset?: number
  fontSize?: number
  color?: string
  font?: FontFamily
  weight?: FontWeight
  decimals?: number
  format?: (value: number) => string
}

/** Numeric labels at evenly spaced values across the arc. */
export const GaugeTickLabels = ({
  count = 10,
  offset = -48,
  fontSize = 16,
  color = "currentColor",
  font = "sans",
  weight = "medium",
  decimals = 0,
  format,
}: GaugeTickLabelsProps) => {
  const gauge = useGauge()
  const { radius, angleOf } = gauge
  const values = tickValues(gauge, count)

  return (
    <g
      fill={color}
      fontSize={fontSize}
      textAnchor="middle"
      dominantBaseline="central"
      className={cn(fontClass[font], weightClass[weight], "tabular-nums")}
    >
      {values.map((value, i) => {
        const p = polar(radius + offset, angleOf(value))
        return (
          <text key={i} x={p.x} y={p.y}>
            {format ? format(value) : value.toFixed(decimals)}
          </text>
        )
      })}
    </g>
  )
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * Dependency-free value animation for the gauge: a damped spring and a
 * cubic-bezier tween, both stepped per frame. Pure functions only; the hook
 * that drives them lives in `use-animated-value.ts`.
 */

/** A named curve, CSS-style cubic-bezier control points, or your own function. */
export type GaugeEasing =
  | "linear"
  | "easeIn"
  | "easeOut"
  | "easeInOut"
  | [number, number, number, number]
  | ((t: number) => number)

export type GaugeSpringTransition = {
  type: "spring"
  /** Physics parameters. When any is given they take precedence over the
      perceptual `visualDuration` and `bounce` pair. */
  stiffness?: number
  damping?: number
  mass?: number
  /** Seconds the spring visibly takes to reach the target. Default 0.5. */
  visualDuration?: number
  /** 0 settles without overshoot, 1 rings freely. Default 0.1. */
  bounce?: number
}

export type GaugeTweenTransition = {
  type: "tween"
  /** Seconds. Default 0.5. */
  duration?: number
  /** Default "easeInOut". */
  ease?: GaugeEasing
}

export type GaugeTransition = GaugeSpringTransition | GaugeTweenTransition

export const DEFAULT_TRANSITION: GaugeSpringTransition = {
  type: "spring",
  visualDuration: 0.5,
  bounce: 0.1,
}

/** Turns the `transition` prop into a concrete config, or null when off. */
export const resolveTransition = (
  transition: GaugeTransition | boolean | undefined
): GaugeTransition | null => {
  if (!transition) return null
  return transition === true ? DEFAULT_TRANSITION : transition
}

/* ---------- spring ---------- */

export type SpringPhysics = { stiffness: number; damping: number; mass: number }

/**
 * Physics for a spring config. The perceptual pair maps onto stiffness and
 * damping the same way the motion library does, so a spring tuned against
 * that library feels the same here.
 */
export const springPhysics = (t: GaugeSpringTransition): SpringPhysics => {
  const hasPhysics =
    t.stiffness !== undefined || t.damping !== undefined || t.mass !== undefined
  if (hasPhysics) {
    return {
      stiffness: t.stiffness ?? 100,
      damping: t.damping ?? 10,
      mass: t.mass ?? 1,
    }
  }
  const visualDuration = t.visualDuration ?? 0.5
  const bounce = t.bounce ?? 0.1
  const root = (2 * Math.PI) / (visualDuration * 1.2)
  const stiffness = root * root
  const ratio = Math.min(1, Math.max(0.05, 1 - bounce))
  return { stiffness, damping: 2 * ratio * Math.sqrt(stiffness), mass: 1 }
}

export type SpringState = { value: number; velocity: number }

const SUBSTEP = 1 / 240

/**
 * Advances a spring by `dt` seconds towards `target` with semi-implicit
 * Euler in small substeps, which stays stable for stiff springs. Returns the
 * new state and whether it has come to rest within `precision`.
 */
export const stepSpring = (
  state: SpringState,
  target: number,
  physics: SpringPhysics,
  dt: number,
  precision: number
): { state: SpringState; done: boolean } => {
  let { value, velocity } = state
  let remaining = Math.min(dt, 0.064)
  while (remaining > 0) {
    const h = Math.min(SUBSTEP, remaining)
    const force =
      -physics.stiffness * (value - target) - physics.damping * velocity
    velocity += (force / physics.mass) * h
    value += velocity * h
    remaining -= h
  }
  const done =
    Math.abs(value - target) < precision && Math.abs(velocity) < precision * 10
  return done
    ? { state: { value: target, velocity: 0 }, done }
    : { state: { value, velocity }, done }
}

/* ---------- tween ---------- */

const namedCurves: Record<
  Exclude<
    GaugeEasing,
    [number, number, number, number] | ((t: number) => number)
  >,
  [number, number, number, number]
> = {
  linear: [0, 0, 1, 1],
  easeIn: [0.42, 0, 1, 1],
  easeOut: [0, 0, 0.58, 1],
  easeInOut: [0.42, 0, 0.58, 1],
}

/** A CSS-compatible cubic-bezier easing function. */
export const cubicBezier = (x1: number, y1: number, x2: number, y2: number) => {
  const bezier = (t: number, p1: number, p2: number) => {
    const u = 1 - t
    return 3 * u * u * t * p1 + 3 * u * t * t * p2 + t * t * t
  }
  const slope = (t: number, p1: number, p2: number) => {
    const u = 1 - t
    return 3 * u * u * p1 + 6 * u * t * (p2 - p1) + 3 * t * t * (1 - p2)
  }
  return (x: number) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    // Newton's method, falling back to bisection where the curve is flat.
    let t = x
    for (let i = 0; i < 8; i++) {
      const dx = bezier(t, x1, x2) - x
      const d = slope(t, x1, x2)
      if (Math.abs(dx) < 1e-6) return bezier(t, y1, y2)
      if (Math.abs(d) < 1e-6) break
      t -= dx / d
    }
    let lo = 0
    let hi = 1
    t = x
    while (hi - lo > 1e-6) {
      if (bezier(t, x1, x2) < x) lo = t
      else hi = t
      t = (lo + hi) / 2
    }
    return bezier(t, y1, y2)
  }
}

/** Resolves any `GaugeEasing` into a function of progress. */
export const easingFunction = (ease: GaugeEasing = "easeInOut") => {
  if (typeof ease === "function") return ease
  const [x1, y1, x2, y2] = Array.isArray(ease) ? ease : namedCurves[ease]
  return cubicBezier(x1, y1, x2, y2)
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useEffect, useRef, useState } from "react"

import {
  easingFunction,
  resolveTransition,
  springPhysics,
  stepSpring,
  type GaugeTransition,
  type SpringState,
} from "./transition"

/** Folds a change into [-span/2, span/2), the short way round a circle. */
const shortestDelta = (delta: number, span: number) => {
  const s = Math.max(span, 1e-9)
  return ((((delta + s / 2) % s) + s) % s) - s / 2
}

/**
 * Follows `target` with the given transition and returns the value to draw
 * this frame. With no transition it returns `target` as is and renders
 * nothing extra. Honours `prefers-reduced-motion` by snapping.
 *
 * `span` is the size of the domain and sets the rest threshold. `initial` is
 * where the value starts on mount, for a sweep-in from the minimum. `wrap`
 * treats the domain as circular: every change is followed the shortest way
 * round, so a heading crossing north never swings the long way back. The
 * returned value may then sit outside the domain mid-flight; map it back
 * with a modulo.
 */
export const useAnimatedValue = (
  target: number,
  transition: GaugeTransition | boolean | undefined,
  span: number,
  initial?: number,
  wrap?: boolean
) => {
  const enabled = Boolean(transition)
  const [display, setDisplay] = useState(initial ?? target)
  const spring = useRef<SpringState>({ value: initial ?? target, velocity: 0 })

  /* With `wrap` the target is folded into a continuous series so the spring
     crosses the seam instead of doubling back. Each change is folded in as
     it renders — the sanctioned way to adjust state to a new prop — and the
     series snaps back to the canonical target at rest, so turning forever
     never drifts far. */
  const start = initial ?? target
  const [series, setSeries] = useState(() => ({
    raw: target,
    goal: wrap ? start + shortestDelta(target - start, span) : target,
  }))
  if (wrap && (target !== series.raw || (!enabled && target !== series.goal))) {
    setSeries(
      enabled
        ? {
            raw: target,
            goal: series.goal + shortestDelta(target - series.raw, span),
          }
        : /* Without a transition the series just shadows the target, so
             re-enabling one starts from what is on screen. */
          { raw: target, goal: target }
    )
  }
  const goal = wrap ? series.goal : target

  // The config is read through a ref so an inline object or easing function
  // does not restart the animation every render; only its content matters.
  const transitionRef = useRef(transition)
  useEffect(() => {
    transitionRef.current = transition
  })
  const configKey = JSON.stringify(transition)

  // While disabled, keep the spring state in step so re-enabling animates
  // from what is on screen rather than from a stale value.
  useEffect(() => {
    if (!enabled) spring.current = { value: target, velocity: 0 }
  }, [enabled, target])

  useEffect(() => {
    const config = resolveTransition(transitionRef.current)
    if (!config) return
    const precision = Math.max(span, 1e-6) * 1e-4
    const snap = prefersReducedMotion()
    /* Where the value comes to rest: the canonical target, so a wrapped
       series that has gone round a few times folds back into the domain. */
    const restAt = target

    let frame = 0
    let last = performance.now()
    const from = spring.current.value
    const start = last

    const tick = (now: number) => {
      const dt = (now - last) / 1000
      last = now
      let done: boolean

      if (snap) {
        done = true
      } else if (config.type === "spring") {
        const physics = springPhysics(config)
        const next = stepSpring(spring.current, goal, physics, dt, precision)
        spring.current = next.state
        done = next.done
      } else {
        const duration = Math.max(config.duration ?? 0.5, 1e-3)
        const progress = Math.min((now - start) / 1000 / duration, 1)
        const eased = easingFunction(config.ease)(progress)
        const value = from + (goal - from) * eased
        spring.current = { value, velocity: 0 }
        done = progress >= 1
      }

      if (done) {
        spring.current = { value: restAt, velocity: 0 }
        if (wrap) {
          setSeries((s) =>
            s.raw === restAt && s.goal === restAt
              ? s
              : { raw: restAt, goal: restAt }
          )
        }
      }
      setDisplay(spring.current.value)
      if (!done) frame = requestAnimationFrame(tick)
    }

    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
  }, [goal, target, configKey, span, wrap])

  return enabled ? display : target
}

const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  typeof window.matchMedia === "function" &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * Shared vocabulary and pure helpers for the gauge primitives: stroke and
 * font options, zones, and the formatters that turn a value into a label.
 * Everything here is framework-free so it can be used in generated code.
 */

export type StrokeCap = "round" | "butt"
export type FontFamily = "sans" | "rounded" | "mono"
export type FontWeight = "regular" | "medium" | "semibold" | "bold"
export type NeedleStyle = "line" | "pointer" | "compass" | "arrow"
/** Which edge of a text sits at its position: left, centre or right. */
export type TextAnchor = "start" | "middle" | "end"

export type Zone = {
  /** Upper cutoff of the zone in domain units. Ignored for the last zone. */
  to: number
  color: string
}

/** `rounded` uses the host sans. The kit does not ship a typeface. */
export const fontClass: Record<FontFamily, string> = {
  sans: "font-sans",
  rounded: "font-sans",
  mono: "font-mono",
}

export const weightClass: Record<FontWeight, string> = {
  regular: "font-normal",
  medium: "font-medium",
  semibold: "font-semibold",
  bold: "font-bold",
}

/** Colour of the zone a value falls in, or `fallback` when there are none. */
export const zoneColor = (zones: Zone[], value: number, fallback: string) => {
  if (zones.length === 0) return fallback
  for (let i = 0; i < zones.length - 1; i++) {
    if (value < zones[i].to) return zones[i].color
  }
  return zones[zones.length - 1].color
}

/** Cutoff values that separate neighbouring zones. */
export const zoneCutoffs = (zones: Zone[]) =>
  zones.slice(0, -1).map((zone) => zone.to)

const compassPoints = [
  "N",
  "NNE",
  "NE",
  "ENE",
  "E",
  "ESE",
  "SE",
  "SSE",
  "S",
  "SSW",
  "SW",
  "WSW",
  "W",
  "WNW",
  "NW",
  "NNW",
]

/**
 * Formats a heading in degrees as a compass point when it lands on one of the
 * sixteen, and as degrees otherwise, so a 0–360 domain reads like a bezel:
 * N, 30°, 60°, E, and so on.
 */
export const compassLabel = (degrees: number) => {
  const turn = ((degrees % 360) + 360) % 360
  const index = Math.round(turn / 22.5) % 16
  const exact = Math.abs(turn - index * 22.5) < 0.5
  return exact ? compassPoints[index] : `${Math.round(turn)}°`
}

/** Formats a value in hours as a clock numeral, so 0 and 12 both read "12". */
export const clockLabel = (hours: number) =>
  String(((Math.round(hours) % 12) + 12) % 12 || 12)

const pad = (n: number) => String(n).padStart(2, "0")

/**
 * Hours past midnight as a 24-hour clock time: 6.5 reads "06:30". Negative
 * hours reach back into the day before, and past 24 into the day after.
 */
export const clockTime = (hours: number) => {
  const minutes = Math.round((((hours % 24) + 24) % 24) * 60)
  return `${pad(Math.floor(minutes / 60) % 24)}:${pad(minutes % 60)}`
}

/** A duration in hours as "7h 32m". */
export const durationLabel = (hours: number) => {
  const minutes = Math.round(hours * 60)
  return `${Math.floor(minutes / 60)}h ${pad(minutes % 60)}m`
}

/**
 * `color` mixed toward the host background so one ink can sit quieter
 * in either theme.
 */
export const fadeColor = (color: string, percent: number) =>
  `color-mix(in srgb, ${color} ${percent}%, var(--background))`

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import type { GaugeInsetSpec, GaugeSpec } from "@/lib/gauge-kit/spec"

/** A prop value emitted verbatim as a JSX expression. */
class Raw {
  constructor(public readonly code: string) {}
}

type PropValue = string | number | boolean | Raw | undefined

const num = (n: number) => Number(n.toFixed(2)).toString()

/** An object or array as a JS literal with unquoted keys. */
const literal = (value: unknown): string => {
  if (Array.isArray(value)) return `[${value.map(literal).join(", ")}]`
  if (typeof value === "number") return num(value)
  if (typeof value === "string") return JSON.stringify(value)
  if (value && typeof value === "object") {
    const entries = Object.entries(value)
      .filter(([, v]) => v !== undefined)
      .map(([k, v]) => `${k}: ${literal(v)}`)
    return `{ ${entries.join(", ")} }`
  }
  return String(value)
}

const prop = (key: string, value: PropValue) => {
  if (value === undefined) return null
  if (value instanceof Raw) return `${key}={${value.code}}`
  if (typeof value === "boolean") return value ? key : `${key}={false}`
  if (typeof value === "number") return `${key}={${num(value)}}`
  return `${key}=${JSON.stringify(value)}`
}

const attributes = (props: Record<string, PropValue>, indent: string) =>
  Object.entries(props)
    .map(([k, v]) => prop(k, v))
    .filter((s): s is string => s !== null)
    .map((a) => `${indent}  ${a}`)
    .join("\n")

const element = (
  tag: string,
  props: Record<string, PropValue>,
  indent: string,
  children?: string
) => {
  const inner = attributes(props, indent)
  if (children === undefined) return `${indent}<${tag}\n${inner}\n${indent}/>`
  return `${indent}<${tag}\n${inner}\n${indent}>\n${indent}  ${children}\n${indent}</${tag}>`
}

/** An element wrapped around elements of its own, already indented. */
const container = (
  tag: string,
  props: Record<string, PropValue>,
  indent: string,
  children: string[]
) =>
  [
    `${indent}<${tag}`,
    attributes(props, indent),
    `${indent}>`,
    ...children,
    `${indent}</${tag}>`,
  ].join("\n")

/** Whether a spec refers to its zone list, by band, marks or arc colour. */
const usesZones = (spec: GaugeSpec) =>
  spec.zones.show || spec.marks.show || (spec.arc.show && spec.arc.colorByZone)

/** The zone list as a `const`, named so insets can each have their own. */
const zonesConst = (spec: GaugeSpec, name: string) =>
  `const ${name} = [\n${spec.zones.list
    .map((zone, i) => {
      const isLast = i === spec.zones.list.length - 1
      const to = isLast ? spec.domain.max : zone.to
      return `  { to: ${num(to)}, color: ${JSON.stringify(zone.color)} },`
    })
    .join("\n")}\n]\n`

type Names = {
  /** The variable holding this gauge's zone list. */
  zones: string
  /** The prop this gauge's value comes in on. */
  value: string
}

/**
 * Everything a spec draws inside its gauge root, mirroring `GaugeParts` in
 * `components/gauge-preview.tsx`. Adds the components it uses to `used`.
 */
const parts = (
  spec: GaugeSpec,
  indent: string,
  used: Set<string>,
  names: Names
) => {
  const body: string[] = []

  if (spec.face.show) {
    used.add("GaugeHub")
    body.push(
      element(
        "GaugeHub",
        { radius: spec.face.radius, color: spec.face.color },
        indent
      )
    )
  }

  if (spec.track.show) {
    used.add("GaugeTrack")
    body.push(
      element(
        "GaugeTrack",
        {
          width: spec.track.width,
          color: spec.track.color,
          opacity: spec.track.opacity,
          cap: spec.track.cap,
          offset: spec.track.offset,
        },
        indent
      )
    )
  }

  if (spec.zones.show) {
    used.add("GaugeZones")
    body.push(
      element(
        "GaugeZones",
        {
          zones: new Raw(names.zones),
          width: spec.zones.width,
          offset: spec.zones.offset,
          gap: spec.zones.gap,
          cap: spec.zones.cap,
          endCap:
            spec.zones.endCap === spec.zones.cap
              ? undefined
              : spec.zones.endCap,
          opacity: spec.zones.opacity,
        },
        indent
      )
    )
  }

  if (spec.arc.show) {
    used.add("GaugeArc")
    body.push(
      element(
        "GaugeArc",
        {
          width: spec.arc.width,
          color: spec.arc.colorByZone
            ? new Raw(
                `zoneColor(${names.zones}, ${names.value}, ${JSON.stringify(spec.arc.color)})`
              )
            : spec.arc.color,
          opacity: spec.arc.opacity,
          cap: spec.arc.cap,
          offset: spec.arc.offset,
          reverse: spec.arc.reverse ? true : undefined,
        },
        indent
      )
    )
  }

  if (spec.marks.show) {
    used.add("GaugeMarks")
    body.push(
      element(
        "GaugeMarks",
        {
          values: new Raw(`zoneCutoffs(${names.zones})`),
          length: spec.marks.length,
          width: spec.marks.width,
          color: spec.marks.color,
          offset: spec.marks.offset,
          cap: spec.marks.cap,
        },
        indent
      )
    )
  }

  for (const ticks of [spec.minorTicks, spec.majorTicks]) {
    if (!ticks.show) continue
    used.add("GaugeTicks")
    body.push(
      element(
        "GaugeTicks",
        {
          count: ticks.count,
          length: ticks.length,
          width: ticks.width,
          color: ticks.color,
          offset: ticks.offset,
          cap: ticks.cap,
          opacity: ticks.opacity,
        },
        indent
      )
    )
  }

  if (spec.tickLabels.show) {
    used.add("GaugeTickLabels")
    const format =
      spec.tickLabels.format === "number"
        ? null
        : `${spec.tickLabels.format}Label`
    if (format) used.add(format)
    body.push(
      element(
        "GaugeTickLabels",
        {
          count: spec.tickLabels.count,
          offset: spec.tickLabels.offset,
          fontSize: spec.tickLabels.fontSize,
          color: spec.tickLabels.color,
          font: spec.tickLabels.font,
          weight: spec.tickLabels.weight,
          decimals: format ? undefined : spec.tickLabels.decimals,
          format: format ? new Raw(format) : undefined,
        },
        indent
      )
    )
  }

  if (spec.needles.show) {
    used.add("GaugeNeedle")
    for (const needle of spec.needles.list) {
      body.push(
        element(
          "GaugeNeedle",
          {
            style: needle.style,
            length: needle.length,
            width: needle.width,
            color: needle.color,
            tail: needle.tail,
            tailColor:
              needle.tailColor === needle.color ? undefined : needle.tailColor,
            tailDot: needle.tailDot > 0 ? needle.tailDot : undefined,
            gap: needle.gap > 0 ? needle.gap : undefined,
            turns: needle.turns === 1 ? undefined : needle.turns,
          },
          indent
        )
      )
    }
    if (spec.needles.hub.radius > 0) {
      used.add("GaugeHub")
      body.push(
        element(
          "GaugeHub",
          { radius: spec.needles.hub.radius, color: spec.needles.hub.color },
          indent
        )
      )
    }
  }

  if (spec.dot.show) {
    used.add("GaugeDot")
    body.push(
      element(
        "GaugeDot",
        {
          radius: spec.dot.radius,
          color: spec.dot.color,
          opacity: spec.dot.opacity,
          offset: spec.dot.offset,
          turns: spec.dot.turns === 1 ? undefined : spec.dot.turns,
        },
        indent
      )
    )
  }

  if (spec.value.show) {
    used.add("GaugeValue")
    body.push(
      element(
        "GaugeValue",
        {
          x: spec.value.x,
          y: spec.value.y,
          fontSize: spec.value.fontSize,
          color: spec.value.color,
          font: spec.value.font,
          weight: spec.value.weight,
          anchor:
            spec.value.anchor === "middle" ? undefined : spec.value.anchor,
          decimals: spec.value.decimals,
        },
        indent
      )
    )
  }

  for (const label of [spec.unit, spec.title]) {
    if (!label.show) continue
    used.add("GaugeText")
    body.push(
      element(
        "GaugeText",
        {
          x: label.x,
          y: label.y,
          fontSize: label.fontSize,
          color: label.color,
          font: label.font,
          weight: label.weight,
          anchor: label.anchor === "middle" ? undefined : label.anchor,
        },
        indent,
        label.text
      )
    )
  }

  if (spec.arc.show && spec.arc.colorByZone) used.add("zoneColor")
  if (spec.marks.show) used.add("zoneCutoffs")

  return body
}

/** The nested gauge for one inset, with all of its own parts inside it. */
const insetElement = (
  inset: GaugeInsetSpec,
  indent: string,
  used: Set<string>
) => {
  used.add("GaugeInset")
  const { domain } = inset.spec
  return container(
    "GaugeInset",
    {
      x: inset.x,
      y: inset.y,
      scale: inset.scale,
      value: new Raw(inset.name),
      min: domain.min,
      max: domain.max,
      startAngle: domain.startAngle,
      endAngle: domain.endAngle,
      /* The inset keeps the host's reference radius and takes its size from
         `scale`, so the radius is only worth printing when it differs. */
      radius: domain.radius === 200 ? undefined : domain.radius,
      transition: inset.spec.transition
        ? new Raw(literal(inset.spec.transition))
        : undefined,
    },
    indent,
    parts(inset.spec, `${indent}  `, used, {
      zones: `${inset.name}Zones`,
      value: inset.name,
    })
  )
}

/** JSX for a component that renders `spec` with the gauge primitives. */
export const gaugeToCode = (spec: GaugeSpec) => {
  const { domain, control } = spec
  const used = new Set<string>(["Gauge"])
  const insets = spec.insets ?? []
  /* A gauge that can be set by hand sits one level down, inside its control. */
  const outer = control ? "      " : "    "
  const pad = `${outer}  `
  if (control) used.add("GaugeControl")

  /* Each gauge gets its own zone list, named after the inset it belongs to. */
  const consts = [usesZones(spec) ? zonesConst(spec, "zones") : null]
  const body = parts(spec, pad, used, { zones: "zones", value: "value" })

  for (const inset of insets) {
    if (usesZones(inset.spec))
      consts.push(zonesConst(inset.spec, `${inset.name}Zones`))
    body.push(insetElement(inset, pad, used))
  }

  /* Every gauge in the tree takes its value from a prop of its own, and one
     that can be set by hand hands the new value back. A gauge on its own
     keeps the one-line signature; a list of them is broken up the way
     prettier would. */
  const params = [
    ["value", "number"],
    ...(control ? [["onChange", "(value: number) => void"]] : []),
    ...insets.map((inset) => [inset.name, "number"]),
  ]
  const signature =
    params.length === 1
      ? `export function CustomGauge({ value }: { value: number }) {`
      : [
          `export function CustomGauge({`,
          ...params.map(([name]) => `  ${name},`),
          `}: {`,
          ...params.map(([name, type]) => `  ${name}: ${type}`),
          `}) {`,
        ].join("\n")

  const gauge = [
    `${outer}<Gauge`,
    `${pad}value={value}`,
    `${pad}min={${num(domain.min)}}`,
    `${pad}max={${num(domain.max)}}`,
    `${pad}startAngle={${num(domain.startAngle)}}`,
    `${pad}endAngle={${num(domain.endAngle)}}`,
    `${pad}radius={${num(domain.radius)}}`,
    `${pad}padding={${num(domain.padding)}}`,
    domain.fit === "content" ? `${pad}fit="content"` : null,
    spec.transition ? `${pad}transition={${literal(spec.transition)}}` : null,
    `${outer}>`,
    ...body,
    `${outer}</Gauge>`,
  ]

  /* The control takes the same domain and sweep as the gauge it turns. */
  const wrapped = control
    ? [
        `    <GaugeControl`,
        `      value={value}`,
        `      onChange={onChange}`,
        `      min={${num(domain.min)}}`,
        `      max={${num(domain.max)}}`,
        `      step={${num(control.step)}}`,
        `      startAngle={${num(domain.startAngle)}}`,
        `      endAngle={${num(domain.endAngle)}}`,
        `      label=${JSON.stringify(spec.title.show ? spec.title.text : "Value")}`,
        control.knob ? `      knob` : null,
        `    >`,
        ...gauge,
        `    </GaugeControl>`,
      ]
    : gauge

  const imports = [...used].sort().join(",\n  ")
  const installed = ["@/", "components/ui/gauge-kit"].join("")

  const lines = [
    `import {\n  ${imports},\n} from "${installed}"`,
    "",
    ...consts,
    signature,
    `  return (`,
    ...wrapped,
    `  )`,
    `}`,
  ]

  return lines.filter((l) => l !== null).join("\n")
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * The studio's own control-panel kit, in the spirit of dialkit but owned by
 * this codebase: a panel is a plain config object — sliders as
 * `[default, min, max, step]` tuples, toggles as booleans, selects, colours,
 * XY pads, transitions and nested folders — parsed once into control metadata
 * and a flat value map keyed by dotted path. React reads it through
 * `useControlPanel` and `ControlsRoot` renders it with shadcn components.
 * There are no presets, no persistence and no timeline: the studio keeps its
 * own state in layers.
 */

/* ---------- config shapes ---------- */

/** The `[default, min, max, step?]` notation used by sliders and pad axes. */
export type SliderTuple = [number, number, number, number?]

export type SpringConfig = {
  type: "spring"
  stiffness?: number
  damping?: number
  mass?: number
  visualDuration?: number
  bounce?: number
}

export type EasingConfig = {
  type: "easing"
  duration: number
  ease: [number, number, number, number]
}

export type TransitionConfig = SpringConfig | EasingConfig

/** A swatch paints a dot beside the label, for options that name a colour. */
export type SelectOption =
  | string
  | { value: string; label: string; swatch?: string }

export type SelectConfig = {
  type: "select"
  options: SelectOption[]
  default?: string
}

export type TextConfig = { type: "text"; default?: string; placeholder?: string }

export type PadAxis = SliderTuple
export type PadValue = { x: number; y: number }
export type PadConfig = {
  type: "pad"
  /** Defaults to [0, -1, 1, 0.01]. */
  x?: PadAxis
  /** Positive Y points upward. Defaults to [0, -1, 1, 0.01]. */
  y?: PadAxis
}

export type ControlValue =
  | number
  | boolean
  | string
  | TransitionConfig
  | SelectConfig
  | TextConfig
  | PadConfig
  | PadValue

export type ControlConfig = {
  [key: string]: ControlValue | SliderTuple | ControlConfig
}

/** A panel config resolved to the values its controls currently hold. */
export type ResolvedValues<T extends ControlConfig> = {
  [K in keyof T]: T[K] extends SliderTuple
    ? number
    : T[K] extends SpringConfig
      ? TransitionConfig
      : T[K] extends EasingConfig
        ? TransitionConfig
        : T[K] extends SelectConfig
          ? string
          : T[K] extends TextConfig
            ? string
            : T[K] extends PadConfig
              ? PadValue
              : T[K] extends ControlConfig
                ? ResolvedValues<T[K]>
                : T[K]
}

/** A partial, nested update in the shape `setValues` accepts. */
export type ControlValueUpdates<T extends ControlConfig> = {
  [K in keyof T as K extends "_collapsed" ? never : K]?: T[K] extends SliderTuple
    ? number
    : T[K] extends SpringConfig | EasingConfig
      ? TransitionConfig
      : T[K] extends SelectConfig | TextConfig
        ? string
        : T[K] extends PadConfig
          ? PadValue
          : T[K] extends ControlConfig
            ? ControlValueUpdates<T[K]>
            : T[K]
}

/* ---------- control metadata ---------- */

export type ControlType =
  | "slider"
  | "toggle"
  | "select"
  | "text"
  | "color"
  | "pad"
  | "transition"
  | "folder"

export type ControlMeta = {
  type: ControlType
  /** The control's dotted path within its panel. */
  path: string
  label: string
  min?: number
  max?: number
  step?: number
  options?: SelectOption[]
  placeholder?: string
  pad?: PadConfig
  defaultOpen?: boolean
  children?: ControlMeta[]
}

export type FlatValues = Record<string, ControlValue>

export type PanelConfig = {
  id: string
  name: string
  controls: ControlMeta[]
  defaultCollapsed: boolean
}

/* ---------- helpers ---------- */

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v)

const hasType = (v: unknown, type: string) => isRecord(v) && v.type === type

export const isTransitionConfig = (v: unknown): v is TransitionConfig =>
  hasType(v, "spring") || hasType(v, "easing")

const isSelectConfig = (v: unknown): v is SelectConfig =>
  hasType(v, "select") && Array.isArray((v as SelectConfig).options)

const isTextConfig = (v: unknown): v is TextConfig => hasType(v, "text")

const isPadConfig = (v: unknown): v is PadConfig => hasType(v, "pad")

export const isPadValue = (v: unknown): v is PadValue =>
  isRecord(v) && typeof v.x === "number" && typeof v.y === "number"

/** Any typed leaf; every other plain object in a config is a folder. */
const isFolderConfig = (v: unknown): v is ControlConfig =>
  isRecord(v) &&
  !isTransitionConfig(v) &&
  !isSelectConfig(v) &&
  !isTextConfig(v) &&
  !isPadConfig(v) &&
  !isPadValue(v)

export const isHexColor = (value: string) =>
  /^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6}|[0-9A-Fa-f]{8})$/.test(value)

/** `startAngle` reads as "Start Angle" on its row. */
export const formatLabel = (key: string) =>
  key
    .replace(/([A-Z])/g, " $1")
    .replace(/^./, (s) => s.toUpperCase())
    .trim()

const inferStep = (min: number, max: number) => {
  const range = max - min
  if (range <= 1) return 0.01
  if (range <= 10) return 0.1
  if (range <= 100) return 1
  return 10
}

/** A sensible range around a bare number, for configs that give only that. */
const inferRange = (value: number) => {
  if (value >= 0 && value <= 1) return { min: 0, max: 1, step: 0.01 }
  if (value >= 0 && value <= 10) return { min: 0, max: value * 3 || 10, step: 0.1 }
  if (value >= 0 && value <= 100)
    return { min: 0, max: value * 3 || 100, step: 1 }
  if (value >= 0) return { min: 0, max: value * 3 || 1000, step: 10 }
  return { min: value * 3, max: -value * 3, step: 1 }
}

/** How many decimals a step needs to print without loss. */
export const stepDecimals = (step: number) =>
  step > 0 && step < 1 ? Math.max(0, Math.ceil(-Math.log10(step))) : 0

/** Clamps into `[min, max]` and snaps onto the step grid anchored at `min`. */
export const snapToStep = (
  value: number,
  step: number | undefined,
  min: number,
  max: number
) => {
  const clamped = Math.min(max, Math.max(min, value))
  if (!step || step <= 0 || !Number.isFinite(clamped)) return clamped
  const base = Number.isFinite(min) ? min : 0
  const snapped = base + Math.round((clamped - base) / step) * step
  /* Re-round to shed float noise like 0.30000000000000004. */
  const tidy = Number(snapped.toFixed(stepDecimals(step) + 2))
  return Math.min(max, Math.max(min, tidy))
}

const optionValue = (option: SelectOption) =>
  typeof option === "string" ? option : option.value

/** A leaf's default: tuples take their head, typed configs their `default`. */
const leafDefault = (raw: unknown): ControlValue => {
  if (Array.isArray(raw)) return raw[0] as number
  if (isSelectConfig(raw))
    return raw.default ?? (raw.options.length ? optionValue(raw.options[0]) : "")
  if (isTextConfig(raw)) return raw.default ?? ""
  if (isPadConfig(raw)) return { x: raw.x?.[0] ?? 0, y: raw.y?.[0] ?? 0 }
  return raw as ControlValue
}

/* ---------- parsing ---------- */

type ParsedConfig = {
  controls: ControlMeta[]
  defaults: FlatValues
  byPath: Map<string, ControlMeta>
}

/** Compiles a config into controls, defaults and a path index in one walk. */
export const parseConfig = (config: ControlConfig): ParsedConfig => {
  const defaults: FlatValues = {}
  const byPath = new Map<string, ControlMeta>()

  const visit = (cfg: ControlConfig, prefix: string): ControlMeta[] => {
    const controls: ControlMeta[] = []
    for (const [key, raw] of Object.entries(cfg)) {
      if (key === "_collapsed") continue
      const path = prefix ? `${prefix}.${key}` : key
      const label = formatLabel(key)
      let control: ControlMeta | undefined
      if (Array.isArray(raw) && typeof raw[0] === "number") {
        control = {
          type: "slider",
          path,
          label,
          min: raw[1],
          max: raw[2],
          step: raw[3] ?? inferStep(raw[1], raw[2]),
        }
      } else if (typeof raw === "number") {
        control = { type: "slider", path, label, ...inferRange(raw) }
      } else if (typeof raw === "boolean") {
        control = { type: "toggle", path, label }
      } else if (isTransitionConfig(raw)) {
        control = { type: "transition", path, label }
      } else if (isSelectConfig(raw)) {
        control = { type: "select", path, label, options: raw.options }
      } else if (isTextConfig(raw)) {
        control = { type: "text", path, label, placeholder: raw.placeholder }
      } else if (isPadConfig(raw)) {
        control = { type: "pad", path, label, pad: raw }
      } else if (typeof raw === "string") {
        /* A bare hex string is a colour to pick; any other string is text. */
        control = { type: isHexColor(raw) ? "color" : "text", path, label }
      } else if (isRecord(raw)) {
        const folder = raw as ControlConfig
        control = {
          type: "folder",
          path,
          label,
          defaultOpen: !folder._collapsed,
          children: visit(folder, path),
        }
      }
      if (!control) continue
      controls.push(control)
      byPath.set(path, control)
      if (control.type !== "folder") defaults[path] = leafDefault(raw)
    }
    return controls
  }

  return { controls: visit(config, ""), defaults, byPath }
}

/** Nests a panel's flat values back into the shape of its config. */
export const resolveValues = <T extends ControlConfig>(
  config: T,
  flat: FlatValues
): ResolvedValues<T> => {
  const visit = (cfg: ControlConfig, prefix: string): Record<string, unknown> => {
    const out: Record<string, unknown> = {}
    for (const [key, raw] of Object.entries(cfg)) {
      if (key === "_collapsed") continue
      const path = prefix ? `${prefix}.${key}` : key
      if (isFolderConfig(raw)) out[key] = visit(raw, path)
      else out[key] = flat[path] !== undefined ? flat[path] : leafDefault(raw)
    }
    return out
  }
  return visit(config, "") as ResolvedValues<T>
}

/**
 * Flattens a nested update into dotted paths, guided by the config: keys the
 * config does not know are dropped. A control that only exists once another
 * value brings it into being — a colour's custom hex — is picked up on a
 * later pass, once the panel has rebuilt around that value.
 */
export const flattenUpdates = (
  config: ControlConfig,
  updates: unknown
): FlatValues => {
  const out: FlatValues = {}
  const visit = (
    cfg: ControlConfig,
    ups: Record<string, unknown>,
    prefix: string
  ) => {
    for (const [key, value] of Object.entries(ups)) {
      if (value === undefined || key === "_collapsed") continue
      const raw = cfg[key]
      if (raw === undefined) continue
      const path = prefix ? `${prefix}.${key}` : key
      if (isFolderConfig(raw)) {
        if (isRecord(value)) visit(raw, value, path)
      } else {
        out[path] = value as ControlValue
      }
    }
  }
  if (isRecord(updates)) visit(config, updates, "")
  return out
}

/**
 * Keeps an existing value across a panel rebuild when it still fits the
 * control, normalised to it: sliders clamp and snap to the new range, selects
 * fall back when their option is gone. A transition keeps whichever shape it
 * has — a spring switched to an easing should not snap back on a rebuild.
 */
const normalizeValue = (
  control: ControlMeta,
  existing: ControlValue | undefined,
  fallback: ControlValue
): ControlValue => {
  if (existing === undefined) return fallback
  switch (control.type) {
    case "slider":
      return typeof existing === "number" && Number.isFinite(existing)
        ? snapToStep(
            existing,
            control.step,
            control.min ?? -Infinity,
            control.max ?? Infinity
          )
        : fallback
    case "toggle":
      return typeof existing === "boolean" ? existing : fallback
    case "select":
      return typeof existing === "string" &&
        (control.options ?? []).some((o) => optionValue(o) === existing)
        ? existing
        : fallback
    case "text":
    case "color":
      return typeof existing === "string" ? existing : fallback
    case "pad": {
      if (!isPadValue(existing)) return fallback
      const clampAxis = (value: number, axis?: PadAxis) =>
        axis
          ? snapToStep(value, axis[3] ?? inferStep(axis[1], axis[2]), axis[1], axis[2])
          : value
      const x = clampAxis(existing.x, control.pad?.x)
      const y = clampAxis(existing.y, control.pad?.y)
      return x === existing.x && y === existing.y ? existing : { x, y }
    }
    case "transition":
      return isTransitionConfig(existing) ? existing : fallback
    default:
      return fallback
  }
}

/* ---------- the store ---------- */

type Listener = () => void

const EMPTY_VALUES: FlatValues = {}

export type PanelOptions = { defaultCollapsed?: boolean }

class ControlsStoreClass {
  private panels = new Map<string, PanelConfig>()
  private values = new Map<string, FlatValues>()
  private byPanel = new Map<string, Map<string, ControlMeta>>()
  private defaults = new Map<string, FlatValues>()
  /* Values kept across an unmount, so strict mode's double mount and a panel
     coming back later pick up where they left off. */
  private retained = new Map<string, FlatValues>()
  private listeners = new Map<string, Set<Listener>>()
  private globalListeners = new Set<Listener>()
  private snapshot: PanelConfig[] = []

  registerPanel(
    id: string,
    name: string,
    config: ControlConfig,
    options: PanelOptions = {}
  ) {
    const previous =
      this.retained.get(id) ?? this.values.get(id) ?? EMPTY_VALUES
    this.setPanel(id, name, config, options, previous)
  }

  updatePanel(
    id: string,
    name: string,
    config: ControlConfig,
    options: PanelOptions = {}
  ) {
    const previous =
      this.values.get(id) ?? this.retained.get(id) ?? EMPTY_VALUES
    this.setPanel(id, name, config, options, previous)
  }

  unregisterPanel(id: string) {
    const values = this.values.get(id)
    if (values) this.retained.set(id, values)
    this.panels.delete(id)
    this.values.delete(id)
    this.byPanel.delete(id)
    this.defaults.delete(id)
    this.notifyGlobal()
  }

  private setPanel(
    id: string,
    name: string,
    config: ControlConfig,
    options: PanelOptions,
    previous: FlatValues
  ) {
    const { controls, defaults, byPath } = parseConfig(config)
    /* Values whose control has left the config stay put — a custom colour
       keeps its hex while the token select is off "custom" — and every value
       the config still has is normalised to its rebuilt control. */
    const values: FlatValues = { ...previous }
    for (const [path, control] of byPath) {
      if (control.type === "folder") continue
      values[path] = normalizeValue(control, previous[path], defaults[path])
    }
    this.panels.set(id, {
      id,
      name,
      controls,
      defaultCollapsed: options.defaultCollapsed ?? false,
    })
    this.values.set(id, values)
    this.byPanel.set(id, byPath)
    this.defaults.set(id, defaults)
    this.retained.delete(id)
    this.notifyGlobal()
    this.notify(id)
  }

  /** A panel's current values, flat and keyed by dotted path. */
  getValues = (id: string): FlatValues => this.values.get(id) ?? EMPTY_VALUES

  /** Every registered panel, in registration order. */
  getPanels = (): PanelConfig[] => this.snapshot

  updateValue(id: string, path: string, value: ControlValue) {
    this.updateValues(id, { [path]: value })
  }

  updateValues(id: string, updates: FlatValues) {
    const values = this.values.get(id)
    if (!values) return
    const byPath = this.byPanel.get(id)
    const defaults = this.defaults.get(id) ?? EMPTY_VALUES
    let changed = false
    const next = { ...values }
    for (const [path, value] of Object.entries(updates)) {
      const control = byPath?.get(path)
      const normalized = control
        ? normalizeValue(control, value, defaults[path] ?? value)
        : value
      if (!Object.is(next[path], normalized)) {
        next[path] = normalized
        changed = true
      }
    }
    if (!changed) return
    this.values.set(id, next)
    this.notify(id)
  }

  subscribe = (id: string, listener: Listener) => {
    let set = this.listeners.get(id)
    if (!set) {
      set = new Set()
      this.listeners.set(id, set)
    }
    set.add(listener)
    return () => {
      set.delete(listener)
      if (set.size === 0) this.listeners.delete(id)
    }
  }

  subscribeGlobal = (listener: Listener) => {
    this.globalListeners.add(listener)
    return () => {
      this.globalListeners.delete(listener)
    }
  }

  private notify(id: string) {
    this.listeners.get(id)?.forEach((fn) => fn())
  }

  private notifyGlobal() {
    this.snapshot = Array.from(this.panels.values())
    this.globalListeners.forEach((fn) => fn())
  }
}

export const ControlsStore = new ControlsStoreClass()

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * The studio edits a composition of gauges: one host and any number of insets
 * inside it. A layer is one of those gauges, held as a full set of panel
 * values, and this is where a list of them turns into the single `GaugeSpec`
 * the preview draws and the code generator prints.
 *
 * Only the selected layer is in the panels at any moment. The rest keep their
 * values here, which is also why every layer stores a complete set: whatever
 * its own panel does not show — the stage colour on an inset, the placement on
 * the host — is still there when the layer comes round again.
 */

import {
  RADIUS,
  buildSpec,
  defaultPanelValues,
  mergeValues,
  withoutMeta,
  type PanelValues,
} from "@/lib/gauge-kit/panels"
import type { GaugeInsetSpec, GaugeSpec } from "@/lib/gauge-kit/spec"

export type GaugeLayer = {
  /** Unique. An inset's is the prop its value arrives on in generated code. */
  id: string
  /** What the layer is called on the chips above the value slider. */
  name: string
  values: PanelValues
}

/** The gauge every composition starts with, the one the insets sit inside. */
export const HOST_ID = "main"

export const hostLayer = (values: PanelValues): GaugeLayer => ({
  id: HOST_ID,
  name: "Main",
  values,
})

/** `fuel` on the chip, and in the generated code, reads as Fuel. */
export const layerName = (id: string) =>
  id.charAt(0).toUpperCase() + id.slice(1)

/** An inset spec for a layer, placed by its own Gauge panel. */
export const insetOf = (layer: GaugeLayer): GaugeInsetSpec => {
  const { position, scale } = layer.values.gauge.placement
  return {
    name: layer.id,
    x: position.x * RADIUS,
    y: -position.y * RADIUS,
    scale,
    value: layer.values.value.value,
    spec: buildSpec(layer.values),
  }
}

/** The whole composition: the first layer is the gauge, the rest its insets. */
export const specFromLayers = (layers: GaugeLayer[]): GaugeSpec => ({
  ...buildSpec(layers[0].values),
  insets: layers.length > 1 ? layers.slice(1).map(insetOf) : undefined,
})

/**
 * A layer with whatever the live panels hold laid over it. The panels carry
 * only the controls their layer's kind shows, so the stored values underneath
 * supply the rest.
 */
export const withLive = (layer: GaugeLayer, live: PanelValues): GaugeLayer => ({
  ...layer,
  values: mergeValues(layer.values, withoutMeta(live)),
})

/** A new inset at the panel defaults, under an id nothing else has taken. */
export const addedLayer = (layers: GaugeLayer[]): GaugeLayer => {
  let n = layers.length + 1
  while (layers.some((layer) => layer.id === `gauge${n}`)) n++
  return { id: `gauge${n}`, name: `Gauge ${n}`, values: defaultPanelValues() }
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * The control panel configs behind the studio, plus the pure functions that
 * turn panel values into a `GaugeSpec`. Kept free of React so templates can
 * be described and previewed against the same source the panels use.
 */

import {
  ControlsStore,
  type ControlConfig,
  type ControlValueUpdates,
  type ResolvedValues,
  type TransitionConfig,
} from "@/lib/gauge-kit/controls"

import { clamp } from "@/components/ui/gauge-kit/math"
import type { GaugeTransition } from "@/components/ui/gauge-kit/transition"
import type {
  FontFamily,
  FontWeight,
  GaugeFit,
  GaugeSpec,
  LabelFormat,
  NeedleSpec,
  NeedleStyle,
  StrokeCap,
  TextAnchor,
  TextSpec,
  TickSpec,
} from "@/lib/gauge-kit/spec"

export const RADIUS = 200

/* ---------- control helpers ---------- */

type Option = string | { value: string; label: string; swatch?: string }
type Select = { type: "select"; options: Option[]; default: string }
type Axis = [number, number, number, number]
type Pad = { type: "pad"; x: Axis; y: Axis }

/** Keeps a toggle's type `boolean` rather than the literal default. */
const toggle = (value: boolean): boolean => value
const select = (options: Option[], value: string): Select => ({
  type: "select",
  options,
  default: value,
})
const cap = (value: StrokeCap = "round") => select(["round", "butt"], value)
const font = (value: FontFamily = "sans") =>
  select(["sans", "rounded", "mono"], value)
const weight = (value: FontWeight = "medium") =>
  select(["regular", "medium", "semibold", "bold"], value)
const anchor = (value: TextAnchor = "middle") =>
  select(["start", "middle", "end"], value)
const position = (x: number, y: number): Pad => ({
  type: "pad",
  x: [x, -1, 1, 0.01],
  y: [y, -1, 1, 0.01],
})

/**
 * A short, named palette. The first entries follow the shadcn theme tokens so
 * the gauge tracks light and dark mode; the last few are fixed accents for
 * status colours the greyscale theme does not provide.
 */
export const palette = [
  { value: "primary", label: "Primary", css: "var(--primary)" },
  { value: "foreground", label: "Foreground", css: "var(--foreground)" },
  { value: "muted", label: "Muted", css: "var(--muted)" },
  {
    value: "muted-foreground",
    label: "Subtle",
    css: "var(--muted-foreground)",
  },
  { value: "background", label: "Background", css: "var(--background)" },
  { value: "destructive", label: "Destructive", css: "var(--destructive)" },
  { value: "chart-1", label: "Chart 1", css: "var(--chart-1)" },
  { value: "chart-2", label: "Chart 2", css: "var(--chart-2)" },
  { value: "chart-3", label: "Chart 3", css: "var(--chart-3)" },
  { value: "chart-4", label: "Chart 4", css: "var(--chart-4)" },
  { value: "chart-5", label: "Chart 5", css: "var(--chart-5)" },
] as const

export type Token = (typeof palette)[number]["value"]

const paletteCss = new Map<string, string>(
  palette.map((entry) => [entry.value, entry.css])
)
/* Older studio saves used these names for the same chart tokens. */
paletteCss.set("green", "var(--chart-2)")
paletteCss.set("amber", "var(--chart-4)")
paletteCss.set("blue", "var(--chart-1)")

const DEFAULT_CUSTOM = "var(--chart-1)"

/** A hint of every colour, for the entry that stands for "any colour". */
const CUSTOM_SWATCH =
  "conic-gradient(from 0.5turn, var(--chart-1), var(--chart-2), var(--chart-3), var(--chart-4), var(--chart-5), var(--chart-1))"

/** The store's current values for a panel, flat and keyed by dotted path. */
export type Flat = Record<string, unknown>
export const flatValues = (panelId: string): Flat =>
  ControlsStore.getValues(panelId)

type ColorFolder = { token: Select; custom: string; _collapsed: true }

/**
 * A colour control: a named palette entry, or "custom" for a free colour.
 * The hex picker is only part of the config while "custom" is selected, so
 * the panel stays compact; `path` is the control's dotted path in the panel
 * and `flat` the panel's current values, used to decide whether to show it.
 *
 * The return type always lists `custom` so resolved values stay easy to
 * type; at runtime it is absent unless custom is selected, and `css` copes.
 */
const color = (flat: Flat, path: string, token: Token): ColorFolder => {
  const folder: Record<string, unknown> = {
    token: select(
      [
        ...palette.map(({ value, label, css }) => ({
          value,
          label,
          swatch: css,
        })),
        { value: "custom", label: "Custom", swatch: CUSTOM_SWATCH },
      ],
      token
    ),
    _collapsed: true,
  }
  if (flat[`${path}.token`] === "custom") {
    const current = flat[`${path}.custom`]
    folder.custom = typeof current === "string" ? current : DEFAULT_CUSTOM
  }
  return folder as ColorFolder
}

export type ColorValue = { token: string; custom?: string }
export const css = (c: ColorValue) =>
  c.token === "custom"
    ? (c.custom ?? DEFAULT_CUSTOM)
    : (paletteCss.get(c.token) ?? `var(--${c.token})`)

/** Slider step that gives about a hundred stops across the domain. */
export const stepFor = (span: number) =>
  span > 0 ? Math.pow(10, Math.floor(Math.log10(span)) - 2) : 1

/* ---------- panel configs ---------- */

export const playModes = ["manual", "sweep", "wander", "jump"] as const
export type PlayMode = (typeof playModes)[number]

/** Which gauge of a composition a panel is editing. */
export type LayerKind = "host" | "inset"

/** Controls only the host has, and the one only an inset has. */
const HOST_ONLY = ["padding", "fit", "stage", "control"] as const
const INSET_ONLY = ["placement"] as const

const without = <T extends object>(config: T, keys: readonly string[]): T =>
  Object.fromEntries(
    Object.entries(config).filter(([key]) => !keys.includes(key))
  ) as T

/**
 * Every control the panel has for either kind of layer. A panel only shows
 * its own kind's, but a layer stores the lot, so the defaults come from here
 * rather than from the trimmed config: an inset added at the defaults still
 * has a `placement` to be drawn by.
 */
const fullGaugeConfig = (flat: Flat = {}) =>
  ({
    min: [0, -100, 100, 1],
    max: [100, 1, 1000, 1],
    /* Runs the whole way round so a dial can start anywhere, including in
       the opening another gauge leaves at the bottom. */
    startAngle: [40, 0, 360, 1],
    /* Runs past 360 so a ring can start at twelve o'clock and close on itself. */
    endAngle: [320, 180, 540, 1],
    padding: [56, 0, 200, 1],
    /* `content` trims the box to the arc's sweep, which only buys anything
       back on gauges that stop well short of a full turn. */
    fit: select(["square", "content"], "square"),
    stage: color(flat, "stage", "background"),
    /* Makes the gauge a slider: drag round the ring, or with `knob` turn the
       face as well. Only a square gauge can be turned, since the drag is
       measured round the middle of its box. */
    control: select(["off", "ring", "knob"], "off"),
    placement: {
      /** Centre in the host gauge, as a fraction of its radius. */
      position: position(0, 0),
      /** Size relative to the host, strokes and text along with it. */
      scale: [0.5, 0.05, 1.5, 0.01],
    },
  }) satisfies ControlConfig

/**
 * The domain and geometry panel. An inset sits inside another gauge rather
 * than in a box of its own, so it trades `padding`, `fit` and the stage
 * colour for where it is placed and how big it is drawn.
 *
 * Both kinds keep the same resolved type, and a layer's stored values fill in
 * whatever its own panel does not show, so the two shapes never have to be
 * told apart downstream.
 */
export const gaugeConfig = (flat: Flat = {}, kind: LayerKind = "host") =>
  without(fullGaugeConfig(flat), kind === "host" ? INSET_ONLY : HOST_ONLY)

/* Panels whose slider ranges follow the domain are built from functions so
   the store can reconcile them when min or max changes. */
export const valueConfig = (min: number, max: number) =>
  ({
    value: [clamp(62, min, max), min, max, stepFor(max - min)],
    /* manual: follow the slider. sweep: min to max and back. wander: drift
       around the slider value. jump: random targets, settled by `motion`. */
    mode: select([...playModes], "manual"),
    period: [3, 0.2, 20, 0.1],
    amplitude: [0.25, 0, 1, 0.01],
    /* How the gauge settles on a new value, in the preview and in the copied
       code alike. Off means the gauge jumps. */
    animate: toggle(true),
    motion: { type: "spring", visualDuration: 0.5, bounce: 0.1 },
  }) satisfies ControlConfig

export const arcsConfig = (flat: Flat = {}) =>
  ({
    track: {
      show: toggle(true),
      width: [24, 1, 80, 1],
      color: color(flat, "track.color", "muted"),
      opacity: [1, 0, 1, 0.01],
      cap: cap("round"),
      offset: [0, -120, 120, 1],
    },
    arc: {
      show: toggle(true),
      width: [24, 1, 80, 1],
      color: color(flat, "arc.color", "primary"),
      colorByZone: toggle(false),
      /* Anchors the fill to the end of the sweep, for a dial that fills
         towards where it starts. */
      reverse: toggle(false),
      opacity: [1, 0, 1, 0.01],
      cap: cap("round"),
      offset: [0, -120, 120, 1],
    },
    face: {
      show: toggle(false),
      radius: [150, 1, 260, 1],
      color: color(flat, "face.color", "muted"),
