/* ---------- values ---------- */

export type GaugeValues = ResolvedValues<ReturnType<typeof gaugeConfig>>
export type ValueValues = ResolvedValues<ReturnType<typeof valueConfig>>
export type ArcsValues = ResolvedValues<ReturnType<typeof arcsConfig>>
export type CutoffsValues = ResolvedValues<ReturnType<typeof cutoffsConfig>>
export type TicksValues = ResolvedValues<ReturnType<typeof ticksConfig>>
export type TextValues = ResolvedValues<ReturnType<typeof textPanelConfig>>
export type NeedleValues = ResolvedValues<ReturnType<typeof needleConfig>>
export type DotValues = ResolvedValues<ReturnType<typeof dotConfig>>

/** Every panel's resolved values, keyed by panel id. */
export type PanelValues = {
  gauge: GaugeValues
  value: ValueValues
  arcs: ArcsValues
  cutoffs: CutoffsValues
  ticks: TicksValues
  text: TextValues
  needle: NeedleValues
  dot: DotValues
}

/** A partial update for every panel, in the shape `setValues` accepts. */
export type PanelUpdates = {
  gauge?: ControlValueUpdates<ReturnType<typeof gaugeConfig>>
  value?: ControlValueUpdates<ReturnType<typeof valueConfig>>
  arcs?: ControlValueUpdates<ReturnType<typeof arcsConfig>>
  cutoffs?: ControlValueUpdates<ReturnType<typeof cutoffsConfig>>
  ticks?: ControlValueUpdates<ReturnType<typeof ticksConfig>>
  text?: ControlValueUpdates<ReturnType<typeof textPanelConfig>>
  needle?: ControlValueUpdates<ReturnType<typeof needleConfig>>
  dot?: ControlValueUpdates<ReturnType<typeof dotConfig>>
}

const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v)

/**
 * Resolves a control config to its default values: sliders take their first
 * element, selects their `default`, pads their axis defaults, and folders
 * recurse. Mirrors what the store does when a panel first registers.
 */
export const defaultsOf = <T extends ControlConfig>(
  config: T
): ResolvedValues<T> => {
  const out: Record<string, unknown> = {}
  for (const [key, raw] of Object.entries(config)) {
    if (key === "_collapsed") continue
    const entry: unknown = raw
    if (Array.isArray(entry)) out[key] = entry[0]
    else if (isRecord(entry) && entry.type === "select")
      out[key] = entry.default
    else if (isRecord(entry) && entry.type === "pad") {
      const pad = entry as unknown as Pad
      out[key] = { x: pad.x[0], y: pad.y[0] }
    } else if (
      isRecord(entry) &&
      (entry.type === "spring" || entry.type === "easing")
    )
      out[key] = entry
    else if (isRecord(entry)) out[key] = defaultsOf(entry as ControlConfig)
    else out[key] = entry
  }
  return out as ResolvedValues<T>
}

/**
 * A deep copy without the keys the panels keep for themselves, such as
 * `_collapsed`.
 * Panel values read back out of the store are fed to `setValues` when a layer
 * comes round again, and those keys are not values to set.
 */
export const withoutMeta = <T>(values: T): T => {
  if (!isRecord(values)) return values
  const out: Record<string, unknown> = {}
  for (const [key, value] of Object.entries(values)) {
    if (key.startsWith("_")) continue
    out[key] = withoutMeta(value)
  }
  return out as T
}

/** Recursively overlays `updates` on `base`; arrays and primitives replace. */
export const mergeValues = <T>(base: T, updates: unknown): T => {
  if (!isRecord(base) || !isRecord(updates)) return (updates ?? base) as T
  const out: Record<string, unknown> = { ...base }
  for (const [key, value] of Object.entries(updates)) {
    if (value === undefined) continue
    out[key] = mergeValues(out[key], value)
  }
  return out as T
}

/** Default values for every panel, at the given domain. */
export const defaultPanelValues = (min = 0, max = 100): PanelValues => ({
  gauge: defaultsOf(fullGaugeConfig()),
  value: defaultsOf(valueConfig(min, max)),
  arcs: defaultsOf(arcsConfig()),
  cutoffs: defaultsOf(cutoffsConfig(min, max)),
  ticks: defaultsOf(ticksConfig()),
  text: defaultsOf(textPanelConfig()),
  needle: defaultsOf(needleConfig()),
  dot: defaultsOf(dotConfig()),
})

/** Panel values for a set of updates applied over the defaults. */
export const resolvePanelValues = (updates: PanelUpdates): PanelValues => {
  const min = updates.gauge?.min ?? gaugeConfig().min[0]
  const max = updates.gauge?.max ?? gaugeConfig().max[0]
  return mergeValues(defaultPanelValues(min, max), updates)
}

/* ---------- spec ---------- */

/** The effective domain after guarding against min crossing max. */
export const domainOf = (gauge: GaugeValues) => ({
  min: Math.min(gauge.min, gauge.max - 1),
  max: gauge.max,
})

/** Turns panel values into the normalised spec the preview and code share. */
/** The gauge's own transition shape for a panel transition control. */
export const toGaugeTransition = (t: TransitionConfig): GaugeTransition => {
  if (t.type === "easing")
    return { type: "tween", duration: t.duration, ease: t.ease }
  const spring: GaugeTransition = { type: "spring" }
  for (const key of [
    "stiffness",
    "damping",
    "mass",
    "visualDuration",
    "bounce",
  ] as const) {
    if (t[key] !== undefined) spring[key] = t[key]
  }
  return spring
}

export const buildSpec = (v: PanelValues): GaugeSpec => {
  const { gauge, value, arcs, cutoffs, ticks, text, needle, dot } = v
  const { min, max } = domainOf(gauge)

  /* Zones keep their panel order. The last zone always runs to `max`, so its
     own cutoff is ignored, and each earlier cutoff is held at or above the
     one before it: dragging a cutoff past its neighbour collapses that zone
     rather than swapping the two colours around. */
  const zoneFolders: { to?: number; color: ColorValue }[] = [
    cutoffs.zone1,
    cutoffs.zone2,
    cutoffs.zone3,
    cutoffs.zone4,
  ].slice(0, cutoffs.count)
  let floor = min
  const zoneList = zoneFolders.map((z, i) => {
    const isLast = i === zoneFolders.length - 1
    const to = isLast ? max : clamp(Math.max(z.to ?? floor, floor), min, max)
    floor = to
    return { to, color: css(z.color) }
  })

  const tick = (t: typeof ticks.major): TickSpec => ({
    show: t.show,
    count: t.count,
    length: t.length,
    width: t.width,
    color: css(t.color),
    offset: t.offset,
    cap: t.cap as StrokeCap,
    opacity: t.opacity,
  })

  const needleSpec = (n: typeof needle.needle1): NeedleSpec => ({
    style: n.style as NeedleStyle,
    length: n.length,
    width: n.width,
    color: css(n.color),
    tail: n.tail,
    tailColor: css(n.tailColor),
    tailDot: n.tailDot,
    gap: n.gap,
    turns: n.turns,
  })

  const label = (t: typeof text.unit): TextSpec => ({
    show: t.show,
    x: t.position.x * RADIUS,
    y: -t.position.y * RADIUS,
    fontSize: t.fontSize,
    color: css(t.color),
    font: t.font as FontFamily,
    weight: t.weight as FontWeight,
    anchor: t.anchor as TextAnchor,
  })

  return {
    transition: value.animate ? toGaugeTransition(value.motion) : undefined,
    control:
      gauge.control === "off" || gauge.fit === "content"
        ? undefined
        : { knob: gauge.control === "knob", step: stepFor(max - min) },
    domain: {
      min,
      max,
      startAngle: gauge.startAngle,
      endAngle: Math.max(gauge.endAngle, gauge.startAngle + 1),
      radius: RADIUS,
      padding: gauge.padding,
      fit: gauge.fit as GaugeFit,
    },
    face: { ...arcs.face, color: css(arcs.face.color) },
    track: {
      ...arcs.track,
      color: css(arcs.track.color),
      cap: arcs.track.cap as StrokeCap,
    },
    arc: {
      ...arcs.arc,
      color: css(arcs.arc.color),
      cap: arcs.arc.cap as StrokeCap,
      colorByZone: cutoffs.show && arcs.arc.colorByZone,
    },
    zones: {
      show: cutoffs.show,
      list: zoneList,
      width: cutoffs.band.width,
      offset: cutoffs.band.offset,
      gap: cutoffs.band.gap,
      cap: cutoffs.band.cap as StrokeCap,
      endCap: cutoffs.band.endCap as StrokeCap,
      opacity: cutoffs.band.opacity,
    },
    marks: {
      ...cutoffs.marks,
      show: cutoffs.show && cutoffs.marks.show,
      color: css(cutoffs.marks.color),
      cap: cutoffs.marks.cap as StrokeCap,
    },
    majorTicks: tick(ticks.major),
    minorTicks: tick(ticks.minor),
    tickLabels: {
      ...ticks.labels,
      color: css(ticks.labels.color),
      font: ticks.labels.font as FontFamily,
      weight: ticks.labels.weight as FontWeight,
      format: ticks.labels.format as LabelFormat,
    },
    needles: {
      show: needle.show,
      list: [needle.needle1, needle.needle2, needle.needle3]
        .slice(0, needle.count)
        .map(needleSpec),
      hub: { radius: needle.hub.radius, color: css(needle.hub.color) },
    },
    dot: { ...dot, color: css(dot.color) },
    value: {
      show: text.value.show,
      x: text.value.position.x * RADIUS,
      y: -text.value.position.y * RADIUS,
      fontSize: text.value.fontSize,
      color: css(text.value.color),
      font: text.value.font as FontFamily,
      weight: text.value.weight as FontWeight,
      anchor: text.value.anchor as TextAnchor,
      decimals: text.value.decimals,
    },
    unit: { ...label(text.unit), text: text.unit.text },
    title: { ...label(text.title), text: text.title.text },
  }
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * A normalised description of a gauge. The studio turns control panel values
 * into a `GaugeSpec`; the preview renders it with the gauge primitives and the
 * code generator prints the equivalent JSX. Keeping one shape in the middle
 * guarantees the copied code matches what is on screen.
 */

import type { GaugeFit } from "@/components/ui/gauge-kit/gauge"
import type { GaugeTransition } from "@/components/ui/gauge-kit/transition"
import type {
  FontFamily,
  FontWeight,
  NeedleStyle,
  StrokeCap,
  TextAnchor,
  Zone,
} from "@/components/ui/gauge-kit/utils"

// The primitive vocabulary and formatters live with the gauge component so
// they ship with it; the studio re-exports them for convenience.
export {
  clockLabel,
  compassLabel,
  fontClass,
  weightClass,
  zoneColor,
  zoneCutoffs,
  type FontFamily,
  type FontWeight,
  type NeedleStyle,
  type StrokeCap,
  type TextAnchor,
  type Zone,
} from "@/components/ui/gauge-kit/utils"
export type { GaugeFit } from "@/components/ui/gauge-kit/gauge"
export type { GaugeTransition } from "@/components/ui/gauge-kit/transition"

/** How tick labels print a value: as a number, a compass point, or an hour. */
export type LabelFormat = "number" | "compass" | "clock"

export type TextSpec = {
  show: boolean
  /** Position in SVG units relative to the gauge centre. Positive y is down. */
  x: number
  y: number
  fontSize: number
  color: string
  font: FontFamily
  weight: FontWeight
  anchor: TextAnchor
}

export type TickSpec = {
  show: boolean
  /** Number of intervals; there is one more tick than intervals. */
  count: number
  length: number
  width: number
  color: string
  offset: number
  cap: StrokeCap
  opacity: number
}

export type NeedleSpec = {
  style: NeedleStyle
  /** Fraction of the radius. */
  length: number
  width: number
  color: string
  tail: number
  tailColor: string
  /** Radius of the disc at the end of the tail; 0 for none. */
  tailDot: number
  /** Radius of the clear circle that splits the needle at the centre; 0 for none. */
  gap: number
  /** Sweeps of the arc across the domain; 1 follows the value directly. */
  turns: number
}

export type GaugeSpec = {
  /** How the gauge settles on a new value. Absent means instant. */
  transition?: GaugeTransition
  /** Set by hand through `GaugeControl`: dragged round the ring, and with
      `knob`, turned by the face as well. Absent means it only shows a value. */
  control?: { knob: boolean; step: number }
  /** Whole gauges drawn inside this one, such as a fuel dial under a speedo. */
  insets?: GaugeInsetSpec[]
  domain: {
    min: number
    max: number
    startAngle: number
    endAngle: number
    radius: number
    padding: number
    /** Square box, or one fitted to the arc's sweep. See `GaugeProps.fit`. */
    fit: GaugeFit
  }
  /** A disc filling the middle, under everything else: a knob's face. */
  face: { show: boolean; radius: number; color: string }
  track: {
    show: boolean
    width: number
    color: string
    opacity: number
    cap: StrokeCap
    offset: number
  }
  arc: {
    show: boolean
    width: number
    color: string
    opacity: number
    cap: StrokeCap
    offset: number
    /** Take the colour of whichever zone the value currently sits in. */
    colorByZone: boolean
    /** Fill back from the end of the sweep rather than forward from the start. */
    reverse: boolean
  }
  zones: {
    show: boolean
    list: Zone[]
    width: number
    offset: number
    gap: number
    /** Cap at the joints between zones. */
    cap: StrokeCap
    /** Cap at the two outer ends of the band. */
    endCap: StrokeCap
    opacity: number
  }
  marks: {
    show: boolean
    length: number
    width: number
    color: string
    offset: number
    cap: StrokeCap
  }
  majorTicks: TickSpec
  minorTicks: TickSpec
  tickLabels: {
    show: boolean
    count: number
    offset: number
    fontSize: number
    color: string
    font: FontFamily
    weight: FontWeight
    decimals: number
    format: LabelFormat
  }
  needles: {
    show: boolean
    list: NeedleSpec[]
    hub: { radius: number; color: string }
  }
  /** A disc riding the arc at the value. See `GaugeDot`. */
  dot: {
    show: boolean
    /** Radius of the dot itself, not the gauge's. */
    radius: number
    color: string
    opacity: number
    offset: number
    turns: number
  }
  value: TextSpec & { decimals: number }
  unit: TextSpec & { text: string }
  title: TextSpec & { text: string }
}

/**
 * A second gauge placed inside the first. The nested spec is a whole gauge in
 * its own right, drawn at `scale` around (`x`, `y`); only its `domain.padding`
 * and `domain.fit` go unused, since an inset shares the host's viewport.
 */
export type GaugeInsetSpec = {
  /** Identifies the inset, and names the prop the generated code reads it from. */
  name: string
  /** Centre in SVG units relative to the host gauge. Positive y is down. */
  x: number
  y: number
  /** Size relative to the host gauge. */
  scale: number
  /** The value on show. The studio's own controls drive the host gauge only. */
  value: number
  spec: GaugeSpec
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * The handful of studio choices that outlive a visit, kept in `localStorage`.
 * Both ends are wrapped: storage throws rather than answering when a browser
 * has it switched off or its quota is full, and a remembered preference is
 * not worth taking the studio down for.
 *
 * Nothing here may be read straight out while rendering. The server has no
 * storage, so a stored value read at the first render would leave the markup
 * and the hydration pass disagreeing. Read it through `useStoredValue`, which
 * hands the first render the fallback and the stored value the moment after,
 * or in an effect for the values that drive something rather than are one.
 */

/** Namespaced, so the studio shares an origin with anything else cleanly. */
export const storageKeys = {
  /** Id of the template the studio was last on. */
  template: "gauge-kit:template",
  /** Whether the controls sidebar is open: `shown` or `hidden`. */
  controls: "gauge-kit:controls",
} as const

export const readStored = (key: string) => {
  try {
    return localStorage.getItem(key)
  } catch {
    return null
  }
}

export const writeStored = (key: string, value: string) => {
  try {
    localStorage.setItem(key, value)
  } catch {
    /* Private modes and full quotas: the choice just does not stick. */
  }
  announce()
}

/* Writes from this tab, which the `storage` event does not report: it is only
   ever fired at the *other* tabs on the origin. Both are passed on, so every
   reader of a key moves together however many of them there are. */
const listeners = new Set<() => void>()

const announce = () => listeners.forEach((listener) => listener())

export const subscribeStored = (onChange: () => void) => {
  listeners.add(onChange)
  window.addEventListener("storage", onChange)
  return () => {
    listeners.delete(onChange)
    window.removeEventListener("storage", onChange)
  }
}

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

/**
 * Starting points for the studio. Each template is a partial update over the
 * panel defaults, in the shape the panel controllers accept, so applying one
 * is "reset, then set". The same updates drive the picker's mini previews.
 *
 * Templates stay within the greyscale theme tokens so they follow light and
 * dark mode; the fixed accents in the palette are left for the user to add.
 * None of them set `padding`, so every preview keeps the panel default and the
 * dials sit in the same frame as each other.
 *
 * A template can also carry `insets`: further gauges, described the same way,
 * drawn inside the first one. They are placed in the host gauge's coordinate
 * space and scaled as a whole, so an inset is simply a smaller dial.
 */

import {
